--
-- Triggers `tbl_accounting_bank_accounts`
--
DELIMITER $$
CREATE TRIGGER `after_add_bank` AFTER INSERT ON `tbl_accounting_bank_accounts` FOR EACH ROW BEGIN
SELECT acc_setting_value into @main_parent FROM tbl_account_setting WHERE acc_setting_name='bank_parent_acc_id';
CALL `sp_get_auto_account_by_parent`(@main_parent, 1, @generated_main);
INSERT INTO tbl_chart_of_accounts SET Account_Name = NEW.Bank_Name, Parent_ID = @main_parent, Account_Code = @generated_main, main_id = NEW.Bank_Account_ID, main_type = 'pay', sub_type = 'credit,check', Currency_ID = NEW.Currency_ID, IsAdded = 1;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `after_update_bank_account` AFTER UPDATE ON `tbl_accounting_bank_accounts` FOR EACH ROW BEGIN UPDATE tbl_chart_of_accounts SET Account_Name = NEW.Bank_Account_Name WHERE main_id = OLD.Bank_Account_ID and main_type='pay';
END
$$
DELIMITER ;

