--
-- Table structure for table `tbl_accounting_transactions`
--

CREATE TABLE `tbl_accounting_transactions` (
  `Transaction_ID` int(11) NOT NULL,
  `JV_ID` int(11) NOT NULL,
  `Transaction_Reference` varchar(255) NOT NULL,
  `user_ref` varchar(255) NOT NULL,
  `Account_ID` bigint(20) NOT NULL,
  `Transaction_Account` varchar(255) NOT NULL,
  `Transaction_Type` varchar(12) NOT NULL,
  `Transaction_Amount` double NOT NULL,
  `Currency_ID` int(11) NOT NULL,
  `Transaction_Date` date NOT NULL,
  `Transaction_Description` longtext NOT NULL,
  `Logged_ID` int(11) NOT NULL,
  `created_logged_id` int(11) NOT NULL,
  `Exchange_Rate_ID` int(11) DEFAULT '0',
  `Current_Ex_Rate` double NOT NULL,
  `local_amount` double NOT NULL DEFAULT '0',
  `second_currency_rate` double NOT NULL DEFAULT '1',
  `second_amount` double NOT NULL DEFAULT '0',
  `third_currency_rate` double NOT NULL DEFAULT '0',
  `fourth_currency_rate` double NOT NULL DEFAULT '0',
  `current_year_id` int(11) NOT NULL DEFAULT '2',
  `date_created` datetime NOT NULL,
  `date_time` datetime NOT NULL,
  `branch_id` int(11) NOT NULL,
  `main_type` varchar(50) NOT NULL,
  `main_id` bigint(20) NOT NULL,
  `sub_id` int(11) DEFAULT NULL,
  `is_actual` tinyint(1) NOT NULL DEFAULT '0',
  `due_date` date NOT NULL,
  `check_nb` int(11) NOT NULL DEFAULT '0',
  `job_id` int(11) DEFAULT NULL,
  `main_nb` int(11) NOT NULL,
  `prefix` varchar(255) NOT NULL,
  `subtype` varchar(255) DEFAULT NULL,
  `value_date` date DEFAULT NULL,
  `project_id` int(11) DEFAULT NULL,
  `pos_customer_id` int(11) NOT NULL DEFAULT '0',
  `salesman_id` int(11) NOT NULL DEFAULT '0',
  `activity_id` int(11) DEFAULT NULL,
  `transaction_param1` varchar(250) DEFAULT NULL,
  `transaction_param2` varchar(250) DEFAULT NULL,
  `is_locked` tinyint(1) NOT NULL DEFAULT '0',
  `is_pending` int(11) NOT NULL DEFAULT '0',
  `bank_cheque_status` tinyint(4) DEFAULT NULL,
  `bank_cheque_nb` int(11) DEFAULT NULL,
  `quickbooks_transaction_id` int(11) DEFAULT NULL,
  `is_cpyact` int(11) NOT NULL DEFAULT '0'
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

--
-- Triggers `tbl_accounting_transactions`
--
DELIMITER $$
CREATE TRIGGER `after_add_transaction` BEFORE INSERT ON `tbl_accounting_transactions` FOR EACH ROW BEGIN SELECT `setting_value` into @local_currency FROM `tbl_default_settings` WHERE `setting_name`='local_currency'; IF @local_currency <> NEW.Currency_ID THEN SELECT Exchange_Rate_ID into @ex_rate_id FROM tbl_currencies_rate WHERE from_currency = NEW.Currency_ID AND to_currency = @local_currency ORDER BY Exchange_Rate_ID DESC LIMIT 1; IF @ex_rate_id IS NULL THEN SELECT Exchange_Rate_ID into @ex_rate_id FROM tbl_currencies_rate WHERE from_currency = @local_currency AND to_currency = NEW.Currency_ID ORDER BY Exchange_Rate_ID DESC LIMIT 1; END IF; SET NEW.Exchange_Rate_ID = @ex_rate_id; END IF;
 END
$$
DELIMITER ;

