--
-- Triggers `tbl_customers`
--
DELIMITER $$
CREATE TRIGGER `add_customer_account` AFTER INSERT ON `tbl_customers` FOR EACH ROW BEGIN
IF @disable_customer_trigger is null then
 SET @acc_types = NEW.cust_acc_types;
    IF NEW.account_parent_id IS NULL THEN
    SELECT acc_setting_value into @main_parent FROM tbl_account_setting WHERE acc_setting_name='customer_main_acc_id';
	ELSE
   SET @main_parent = NEW.account_parent_id;
    end if;
 CALL `sp_get_auto_account_by_parent`(@main_parent, 1, @generated_main); 
     INSERT INTO tbl_chart_of_accounts
        SET
            Account_Name = NEW.Customer_Name,
            Parent_ID = @main_parent,
            Account_Code = @generated_main,
            main_id = NEW.Customer_ID,
            main_type = 'cust',
            sub_type = 'main',
            Currency_ID = NEW.Currency_ID,
			IsAdded = 1;

if concat(',',@acc_types,',') like "%,vat,%" then
    SELECT acc_setting_value into @parent_id_vat FROM tbl_account_setting WHERE acc_setting_name='customer_vat_acc_id';
       CALL `sp_get_auto_account_by_parent`(@parent_id_vat, 1, @generated_vat);
   INSERT INTO tbl_chart_of_accounts
        SET
            Account_Name = NEW.Customer_Name,
            Parent_ID = @parent_id_vat,
            Account_Code = @generated_vat,
            main_id = NEW.Customer_ID,
            main_type = 'cust',
            sub_type = 'vat',
            Currency_ID = NEW.Currency_ID,
			IsAdded = 1;
end if;

if concat(',',@acc_types,',') like "%,bill,%" then
    SELECT acc_setting_value into @parent_id FROM tbl_account_setting WHERE acc_setting_name='customer_bill_acc_id';
       CALL `sp_get_auto_account_by_parent`(@parent_id, 1, @generated_acc);
   INSERT INTO tbl_chart_of_accounts
        SET
            Account_Name = NEW.Customer_Name,
            Parent_ID = @parent_id,
            Account_Code = @generated_acc,
            main_id = NEW.Customer_ID,
            main_type = 'cust',
            sub_type = 'bill',
            Currency_ID = NEW.Currency_ID,
			IsAdded = 1;
end if;

end if;
end
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `after_update_customer` AFTER UPDATE ON `tbl_customers` FOR EACH ROW BEGIN

IF OLD.Customer_Name <> NEW.Customer_Name THEN
	UPDATE tbl_chart_of_accounts
	SET Account_Name = NEW.Customer_Name
    WHERE main_id = OLD.Customer_ID and main_type='cust';
END IF;

IF OLD.Currency_ID <> NEW.Currency_ID THEN
	UPDATE tbl_chart_of_accounts
	SET Currency_ID = NEW.Currency_ID
	WHERE main_id = OLD.Customer_ID and main_type='cust';
END IF;

IF (ifnull(OLD.account_parent_id,0) <>  ifnull(NEW.account_parent_id,0) ) THEN
	IF NEW.account_parent_id IS NULL THEN
		SELECT acc_setting_value into @main_parent FROM tbl_account_setting WHERE acc_setting_name='customer_main_acc_id';
	ELSE
		SET @main_parent = NEW.account_parent_id;
    end if;
	 CALL `sp_get_auto_account_by_parent`(@main_parent, 1, @main_code); 
	UPDATE 
		tbl_chart_of_accounts
	SET 
		Account_Code = @main_code,
        Parent_ID = @main_parent
	WHERE 
		main_id = OLD.Customer_ID
        and main_type='cust' and sub_type = 'main';
END IF;

if(NEW.cust_acc_types <> OLD.cust_acc_types) then
           set @old_types = OLD.cust_acc_types;
            set @next = '';
            set @nextlen=0;
            iterator:
            LOOP

              IF LENGTH(TRIM(@old_types)) = 0 OR @old_types IS NULL THEN
                LEAVE iterator;
              END IF;

              SET @next = SUBSTRING_INDEX(@old_types,',',1);
            if concat(',',NEW.cust_acc_types,',') not like concat("%,",@next,",%") then
                select Account_ID into @acc_id from tbl_chart_of_accounts where main_type = 'cust' and sub_type=@next and main_id=OLD.Customer_ID;
                select count(*) into @trans_count from tbl_accounting_transactions where Account_ID = @acc_id;
                    if @trans_count = 0 then
                        delete from tbl_chart_of_accounts where Account_ID = @acc_id;
                    end if;
            end if;
            SET @nextlen = LENGTH(@next);
            set @old_types= INSERT(@old_types,1,@nextlen + 1,'');
    END LOOP;
 set @new_types = NEW.cust_acc_types;
            set @next = '';
            set @nextlen=0;
            iterator1:
            LOOP

              IF LENGTH(TRIM(@new_types)) = 0 OR @new_types IS NULL THEN
                LEAVE iterator1;
              END IF;

              SET @next = SUBSTRING_INDEX(@new_types,',',1);
            if concat(',',NEW.cust_acc_types,',') like concat("%,",@next,",%") then
                select count(Account_ID) into @acc_count from tbl_chart_of_accounts where main_type = 'cust' and sub_type=@next and main_id=OLD.Customer_ID;
                if @acc_count=0 then
                    set @parent=0;
                    if @next = 'vat' then
                        SELECT acc_setting_value into @parent FROM tbl_account_setting WHERE acc_setting_name='customer_vat_acc_id';
                    end if;
                    if @next = 'bill' then
                        SELECT acc_setting_value into @parent FROM tbl_account_setting WHERE acc_setting_name='customer_bill_acc_id';
                    end if;
                     if @next = 'main' then
                        SELECT acc_setting_value into @parent FROM tbl_account_setting WHERE acc_setting_name='customer_main_acc_id';
                    end if;
                    CALL `sp_get_auto_account_by_parent`(@parent, 1, @code); 
                    insert into tbl_chart_of_accounts (Account_Code,Account_Name,Parent_ID,main_id,main_type,sub_type,Currency_ID,IsAdded)
                    VALUES (@code,NEW.Customer_Name,@parent,NEW.Customer_ID,'cust',@next,NEW.Currency_ID,1);

                end if;
            end if;
            SET @nextlen = LENGTH(@next);
            set @new_types= INSERT(@new_types,1,@nextlen + 1,'');
    END LOOP;
end if;
END
$$
DELIMITER ;

