--
-- Triggers `tbl_hrm_employee`
--
DELIMITER $$
CREATE TRIGGER `after_add_employee` AFTER INSERT ON `tbl_hrm_employee` FOR EACH ROW BEGIN
IF NEW.Status_ID = 1 and NEW.emp_acc_entry_id=0 THEN
            SET @employee_name = CONCAT(NEW.Employee_FirstName,if(NEW.Employee_MiddleName="", "", concat(" ",NEW.Employee_MiddleName)), " ", NEW.Employee_LastName);

         SELECT acc_setting_value into @exp_parent FROM tbl_account_setting WHERE acc_setting_name='emp_exp_parent_acc_id';
               
                CALL `sp_get_auto_account_by_parent`(@exp_parent, 1, @main_exp_code);
                set @exp_code =  @main_exp_code;
                       INSERT INTO tbl_chart_of_accounts
        SET
            Account_Name = @employee_name,
            Parent_ID = @exp_parent,
            Account_Code = @exp_code,
            main_id = NEW.Employee_ID,
            main_type = 'emp',
            sub_type = 'exp',
			IsAdded = 1;


             SELECT acc_setting_value into @income_parent FROM tbl_account_setting WHERE acc_setting_name='emp_income_parent_acc_id';
                
                CALL `sp_get_auto_account_by_parent`(@income_parent, 1, @main_income_code);
                
                
                set @income_code = @main_income_code;
               
               
               
               

            
            INSERT INTO tbl_chart_of_accounts
        SET
            Account_Name = @employee_name,
            Parent_ID = @income_parent,
            Account_Code = @income_code,
            main_id = NEW.Employee_ID,
            main_type = 'emp',
            sub_type = 'inc',
			IsAdded = 1;
            
END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `after_update_employee` AFTER UPDATE ON `tbl_hrm_employee` FOR EACH ROW BEGIN
set @old_name = CONCAT(OLD.Employee_FirstName,if(OLD.Employee_MiddleName="", "", concat(" ",OLD.Employee_MiddleName)), " ", OLD.Employee_LastName);
set @new_name = CONCAT(NEW.Employee_FirstName, if(NEW.Employee_MiddleName="", "", concat(" ",NEW.Employee_MiddleName)), " ", NEW.Employee_LastName);

IF NEW.Status_ID = 1 and NEW.emp_acc_entry_id=0 THEN
 
              select Account_ID into @exp_old_acc from tbl_chart_of_accounts where main_id =  NEW.Employee_ID and main_type="emp" and sub_type='exp';
              if isnull(@exp_old_acc) then
               
               SELECT acc_setting_value into @exp_parent FROM tbl_account_setting WHERE acc_setting_name='emp_exp_parent_acc_id';
               
                CALL `sp_get_auto_account_by_parent`(@exp_parent, 1, @main_exp_code);
                set @exp_code =  @main_exp_code;         
       INSERT INTO tbl_chart_of_accounts
        SET
            Account_Name = @new_name,
            Parent_ID = @exp_parent,
            Account_Code = @exp_code,
            main_id = NEW.Employee_ID,
            main_type = 'emp',
            sub_type = 'exp',
			IsAdded = 1;
            end if;
            select Account_ID into @inc_old_acc from tbl_chart_of_accounts where main_id =  NEW.Employee_ID and main_type="emp" and sub_type='inc';
              if isnull(@inc_old_acc) then
                         SELECT acc_setting_value into @income_parent FROM tbl_account_setting WHERE acc_setting_name='emp_income_parent_acc_id';
                
                CALL `sp_get_auto_account_by_parent`(@income_parent, 1, @main_income_code);
                
                
                set @income_code = @main_income_code;
            INSERT INTO tbl_chart_of_accounts
        SET
            Account_Name = @new_name,
            Parent_ID = @income_parent,
            Account_Code = @income_code,
            main_id = NEW.Employee_ID,
            main_type = 'emp',
            sub_type = 'inc',
			IsAdded = 1;
            end if;
END IF;

IF @old_name <> @new_name THEN

	UPDATE 
		tbl_chart_of_accounts
	SET 
		Account_Name = @new_name
	WHERE 
		main_id = OLD.Employee_ID
        and main_type='emp';

END IF;
END
$$
DELIMITER ;

