--
-- Triggers `tbl_invoices`
--
DELIMITER $$
CREATE TRIGGER `after_add_invoice` AFTER INSERT ON `tbl_invoices` FOR EACH ROW begin IF NEW.Is_Closed = 0 and ifNull(NEW.table_id, 0) <> 0 THEN UPDATE tbl_table SET status_id = 2,
 user_id = NEW.Close_ID WHERE table_id = NEW.table_id; END IF; 
end
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `after_update_invoice` AFTER UPDATE ON `tbl_invoices` FOR EACH ROW begin 

IF NEW.Is_Closed <> OLD.Is_Closed OR NEW.Close_ID <> OLD.Close_ID OR NEW.table_id <> OLD.table_id OR NEW.Related_Tables <> OLD.Related_Tables THEN 
	IF ifNull(OLD.table_id, 0) <> 0 THEN
		UPDATE tbl_table SET status_id = 1, user_id = null, table_alias_name = null 
WHERE (table_id = OLD.table_id or concat(",",OLD.Related_Tables,",") like concat("%,",table_id,",%"))
and table_id <> NEW.table_id and concat(",",NEW.Related_Tables,",") not like concat("%,",table_id,",%");
	END IF;
	IF ifNull(NEW.table_id, 0) <> 0 THEN
		IF NEW.Is_Closed = 1 THEN
			UPDATE tbl_table SET status_id = 1, user_id = null, table_alias_name = null 
WHERE (table_id = NEW.table_id or concat(",",NEW.Related_Tables,",") like concat("%,",table_id,",%"));
		ELSE
			UPDATE tbl_table SET status_id = 2, user_id = NEW.Close_ID
WHERE (table_id = NEW.table_id or concat(",",NEW.Related_Tables,",") like concat("%,",table_id,",%"));
		END IF;
	END IF;
END IF;

end
$$
DELIMITER ;

