--
-- Table structure for table `tbl_mgt_logs`
--

CREATE TABLE `tbl_mgt_logs` (
  `Transaction_ID` int(11) NOT NULL,
  `JV_ID` int(11) NOT NULL,
  `Transaction_Reference` varchar(32) CHARACTER SET utf8 NOT NULL,
  `Transaction_Account` varchar(255) CHARACTER SET utf8 NOT NULL,
  `Transaction_Type` varchar(12) CHARACTER SET utf8 NOT NULL,
  `Transaction_Amount` double NOT NULL,
  `Currency_ID` int(11) NOT NULL,
  `Transaction_Date` date NOT NULL,
  `Transaction_Description` longtext CHARACTER SET utf8 NOT NULL,
  `Logged_ID` int(11) NOT NULL,
  `Exchange_Rate_ID` int(11) NOT NULL,
  `Current_Ex_Rate` double NOT NULL,
  `current_year_id` int(11) NOT NULL,
  `date_time` varchar(200) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

--
-- Triggers `tbl_mgt_logs`
--
DELIMITER $$
CREATE TRIGGER `after_add_transaction_mgt` BEFORE INSERT ON `tbl_mgt_logs` FOR EACH ROW BEGIN
    SET @local_currency = (SELECT Local_Currency FROM tbl_organization);
    
    IF @local_currency <> NEW.Currency_ID THEN
        SET @ex_rate_id = (SELECT
                                Exchange_Rate_ID
                            FROM
                                tbl_currencies_rate
                            WHERE
                                from_currency = NEW.Currency_ID
                            AND
                                to_currency = @local_currency
                            ORDER BY 
                                Exchange_Rate_ID
                            DESC 
                            LIMIT 1);
        IF @ex_rate_id IS NULL THEN
            SET @ex_rate_id = (SELECT
                                    Exchange_Rate_ID
                                FROM
                                    tbl_currencies_rate
                                WHERE
                                    from_currency = @local_currency
                                AND
                                    to_currency = NEW.Currency_ID
                                ORDER BY 
                                    Exchange_Rate_ID
                                DESC 
                                LIMIT 1);
        END IF;
        
        SET 
            NEW.Exchange_Rate_ID = @ex_rate_id;
    END IF;
    

END
$$
DELIMITER ;

