--
-- Table structure for table `tbl_stock_cost_average`
--

CREATE TABLE `tbl_stock_cost_average` (
  `Product_Cost_ID` int(11) NOT NULL,
  `Product_ID` int(11) NOT NULL,
  `Unit_Cost` double NOT NULL,
  `Currency_ID` int(11) NOT NULL,
  `Exchange_Rate_ID` int(11) NOT NULL,
  `Purchase_Date` date NOT NULL,
  `Status_ID` tinyint(1) NOT NULL DEFAULT '1',
  `Product_Quantity` double NOT NULL,
  `date_time` varchar(200) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

--
-- Triggers `tbl_stock_cost_average`
--
DELIMITER $$
CREATE TRIGGER `after_insert_cost_average` BEFORE INSERT ON `tbl_stock_cost_average` FOR EACH ROW BEGIN
    SELECT `setting_value` into @local_currency FROM `tbl_default_settings` WHERE `setting_name`='local_currency';
    
    IF @local_currency <> NEW.Currency_ID THEN
        SELECT Exchange_Rate_ID into  @ex_rate_id
                            FROM
                                tbl_currencies_rate
                            WHERE
                                from_currency = NEW.Currency_ID
                            AND
                                to_currency = @local_currency
                            ORDER BY 
                                Exchange_Rate_ID
                            DESC 
                            LIMIT 1;
        IF @ex_rate_id IS NULL THEN
         SELECT Exchange_Rate_ID into @ex_rate_id
                                FROM
                                    tbl_currencies_rate
                                WHERE
                                    from_currency = @local_currency
                                AND
                                    to_currency = NEW.Currency_ID
                                ORDER BY 
                                    Exchange_Rate_ID
                                DESC 
                                LIMIT 1;
        END IF;
        
        SET 
            NEW.Exchange_Rate_ID = @ex_rate_id;
    END IF;
    

END
$$
DELIMITER ;

