  `fourth_currency_rate` double NOT NULL DEFAULT '0',
  `remaining_quantity` double NOT NULL DEFAULT '0'
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

--
-- Triggers `tbl_stock_products_costs`
--
DELIMITER $$
CREATE TRIGGER `tbl_cost_trigger` BEFORE INSERT ON `tbl_stock_products_costs` FOR EACH ROW BEGIN
    SELECT `setting_value` into @local_currency FROM `tbl_default_settings` WHERE `setting_name`='local_currency';
    
    IF @local_currency <> NEW.Currency_ID THEN
       SELECT
                                Exchange_Rate_ID into @ex_rate_id
                            FROM
                                tbl_currencies_rate
                            WHERE
                                from_currency = NEW.Currency_ID
                            AND
                                to_currency = @local_currency
                            ORDER BY 
                                Exchange_Rate_ID
                            DESC 
                            LIMIT 1;
        IF @ex_rate_id IS NULL THEN
            SELECT
                                    Exchange_Rate_ID into  @ex_rate_id 
                                FROM
                                    tbl_currencies_rate
                                WHERE
                                    from_currency = @local_currency
                                AND
                                    to_currency = NEW.Currency_ID
                                ORDER BY 
                                    Exchange_Rate_ID
                                DESC 
                                LIMIT 1;
        END IF;
        
        SET 
            NEW.Exchange_Rate_ID = @ex_rate_id;
    END IF;
    

END
$$
DELIMITER ;

