--
-- Triggers `tbl_stock_suppliers`
--
DELIMITER $$
CREATE TRIGGER `add_supplier_account` AFTER INSERT ON `tbl_stock_suppliers` FOR EACH ROW BEGIN 
IF @disable_supplier_trigger is null then
    SET @acc_types = NEW.supp_acc_types;
    SELECT VAT_Type_ID into @vat_type FROM tbl_organization WHERE Organization_ID = 1;

IF NEW.account_parent_id IS NULL THEN
    SELECT acc_setting_value into @main_parent FROM tbl_account_setting WHERE acc_setting_name='supplier_main_acc_id';
ELSE
    SET @main_parent = NEW.account_parent_id;
end if;
CALL `sp_get_auto_account_by_parent`(@main_parent, 1, @main_code); 
insert into tbl_chart_of_accounts (Account_Code,Account_Name,Parent_ID,main_id,main_type,sub_type,Currency_ID,IsAdded)
    VALUES (@main_code,NEW.Supplier_Name,@main_parent,NEW.Supplier_ID,'supp','main',NEW.Currency_ID,1);

if concat(',',@acc_types,',') like "%,exp,%" then
    SELECT acc_setting_value into @exp_parent FROM tbl_account_setting WHERE acc_setting_name='supplier_exp_acc_id';
    CALL `sp_get_auto_account_by_parent`(@exp_parent, 1, @exp_code); 
insert into tbl_chart_of_accounts (Account_Code,Account_Name,Parent_ID,main_id,main_type,sub_type,Currency_ID,IsAdded)
    VALUES (@exp_code,NEW.Supplier_Name,@exp_parent,NEW.Supplier_ID,'supp','exp',NEW.Currency_ID,1);
end if;

if concat(',',@acc_types,',') like "%,fa,%" then
    SELECT acc_setting_value into @fa_parent FROM tbl_account_setting WHERE acc_setting_name='supplier_fa_acc_id';
    CALL `sp_get_auto_account_by_parent`(@fa_parent, 1, @fa_code); 
insert into tbl_chart_of_accounts (Account_Code,Account_Name,Parent_ID,main_id,main_type,sub_type,Currency_ID,IsAdded)
    VALUES (@fa_code,NEW.Supplier_Name,@fa_parent,NEW.Supplier_ID,'supp','fa',NEW.Currency_ID,1);
end if;

if concat(',',@acc_types,',') like "%,pur_vat,%" then
    SELECT acc_setting_value into @vat_pur FROM tbl_account_setting WHERE acc_setting_name=if(@vat_type = 1,
                    'supplier_pur_vat_acc_id','supplier_pur_vat_partial_acc_id');
    CALL `sp_get_auto_account_by_parent`(@vat_pur, 1, @vat_pur_code); 
insert into tbl_chart_of_accounts (Account_Code,Account_Name,Parent_ID,main_id,main_type,sub_type,Currency_ID,IsAdded)
    VALUES (@vat_pur_code,NEW.Supplier_Name,@vat_pur,NEW.Supplier_ID,'supp','pur_vat',NEW.Currency_ID,1);
end if;

if concat(',',@acc_types,',') like "%,exp_vat,%" then
    SELECT acc_setting_value into @vat_exp FROM tbl_account_setting WHERE acc_setting_name=if(@vat_type =1,
                    'supplier_exp_vat_acc_id','supplier_exp_vat_partial_acc_id');
    CALL `sp_get_auto_account_by_parent`(@vat_exp, 1, @vat_exp_code); 
insert into tbl_chart_of_accounts (Account_Code,Account_Name,Parent_ID,main_id,main_type,sub_type,Currency_ID,IsAdded)
    VALUES (@vat_exp_code,NEW.Supplier_Name,@vat_exp,NEW.Supplier_ID,'supp','exp_vat',NEW.Currency_ID,1);
end if;
   
if concat(',',@acc_types,',') like "%,fa_vat,%" then
    SELECT acc_setting_value into @vat_fa FROM tbl_account_setting WHERE acc_setting_name=if(@vat_type = 1,
                    'supplier_fa_vat_acc_id','supplier_fa_vat_partial_acc_id');
   CALL `sp_get_auto_account_by_parent`(@vat_fa, 1, @vat_fa_code); 
     insert into tbl_chart_of_accounts (Account_Code,Account_Name,Parent_ID,main_id,main_type,sub_type,Currency_ID,IsAdded)
    VALUES (@vat_fa_code,NEW.Supplier_Name,@vat_fa,NEW.Supplier_ID,'supp','fa_vat',NEW.Currency_ID,1);
end if;
    
 
end if;
end
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `after_update_supplier` AFTER UPDATE ON `tbl_stock_suppliers` FOR EACH ROW BEGIN

IF OLD.Supplier_Name <> NEW.Supplier_Name THEN
	UPDATE tbl_chart_of_accounts
	SET Account_Name = NEW.Supplier_Name
	WHERE  main_id = OLD.Supplier_ID and main_type='supp';
END IF;

IF OLD.Currency_ID <> NEW.Currency_ID THEN
	UPDATE tbl_chart_of_accounts
	SET Currency_ID = NEW.Currency_ID
	WHERE  main_id = OLD.Supplier_ID and main_type='supp';
END IF;

IF (ifnull(OLD.account_parent_id,0) <>  ifnull(NEW.account_parent_id,0) ) THEN
        
	IF NEW.account_parent_id IS NULL THEN
		SELECT acc_setting_value into @main_parent FROM tbl_account_setting WHERE acc_setting_name='supplier_main_acc_id';
	ELSE
		SET @main_parent = NEW.account_parent_id;
    end if;
	 CALL `sp_get_auto_account_by_parent`(@main_parent, 1, @main_code); 
	UPDATE 
		tbl_chart_of_accounts
	SET 
		Account_Code = @main_code,
        Parent_ID = @main_parent
	WHERE 
		main_id = OLD.Supplier_ID
        and main_type='supp' and sub_type = 'main';
	
END IF;

        if(NEW.supp_acc_types <> OLD.supp_acc_types) then
           set @old_types = OLD.supp_acc_types;
            set @next = '';
            set @nextlen=0;
            iterator:
            LOOP

              IF LENGTH(TRIM(@old_types)) = 0 OR @old_types IS NULL THEN
                LEAVE iterator;
              END IF;

              SET @next = SUBSTRING_INDEX(@old_types,',',1);
            if concat(',',NEW.supp_acc_types,',') not like concat("%,",@next,",%") then
                select Account_ID into @acc_id from tbl_chart_of_accounts where main_type = 'supp' and sub_type=@next and main_id=OLD.Supplier_ID;
                select count(*) into @trans_count from tbl_accounting_transactions where Account_ID = @acc_id;
                    if @trans_count = 0 then
                        delete from tbl_chart_of_accounts where Account_ID = @acc_id;
                    end if;
            end if;
            SET @nextlen = LENGTH(@next);
            set @old_types= INSERT(@old_types,1,@nextlen + 1,'');
    END LOOP;
 SELECT VAT_Type_ID into @vat_type FROM tbl_organization WHERE Organization_ID = 1;


            set @new_types = NEW.supp_acc_types;
            set @next = '';
            set @nextlen=0;
            iterator1:
            LOOP

              IF LENGTH(TRIM(@new_types)) = 0 OR @new_types IS NULL THEN
                LEAVE iterator1;
              END IF;

              SET @next = SUBSTRING_INDEX(@new_types,',',1);
            if concat(',',NEW.supp_acc_types,',') like concat("%,",@next,",%") then
                select count(Account_ID) into @acc_count from tbl_chart_of_accounts where main_type = 'supp' and sub_type=@next and main_id=OLD.Supplier_ID;
                if @acc_count=0 and @next <>'main' then
                    set @parent=0;
                    if @next = 'pur_vat' then
                        SELECT acc_setting_value into @parent FROM tbl_account_setting WHERE acc_setting_name=if(@vat_type = 1,
                        'supplier_pur_vat_acc_id','supplier_pur_vat_partial_acc_id');
                    end if;
                   
                    if @next ='exp_vat' then
                        SELECT acc_setting_value into @parent FROM tbl_account_setting WHERE acc_setting_name=if(@vat_type =1,
                        'supplier_exp_vat_acc_id','supplier_exp_vat_partial_acc_id');
                    end if;
                   
                    if @next ='fa_vat' then
                        SELECT acc_setting_value into @parent FROM tbl_account_setting WHERE acc_setting_name=if(@vat_type = 1,
                        'supplier_fa_vat_acc_id','supplier_fa_vat_partial_acc_id');
                    end if;
                    
                    
                    if @next ='fa' then
                        SELECT acc_setting_value into @parent FROM tbl_account_setting WHERE acc_setting_name=concat('supplier_fa_acc_id');
                    end if;
                    if @next ='exp' then
                    SELECT acc_setting_value into @parent FROM tbl_account_setting WHERE acc_setting_name=concat('supplier_exp_acc_id');
                    end if;
                      if @next ='main' then
                    SELECT acc_setting_value into @parent FROM tbl_account_setting WHERE acc_setting_name=concat('supplier_main_acc_id');
                    end if;

                    CALL `sp_get_auto_account_by_parent`(@parent, 1, @code); 
                    insert into tbl_chart_of_accounts (Account_Code,Account_Name,Parent_ID,main_id,main_type,sub_type,Currency_ID,IsAdded)
                    VALUES (@code,NEW.Supplier_Name,@parent,NEW.Supplier_ID,'supp',@next,NEW.Currency_ID,1);

                end if;
            end if;
            SET @nextlen = LENGTH(@next);
            set @new_types= INSERT(@new_types,1,@nextlen + 1,'');
    END LOOP;

        end if;
END
$$
DELIMITER ;

