--
-- Table structure for table `wp_message`
--

CREATE TABLE `wp_message` (
  `wp_message_id` int(11) NOT NULL,
  `wp_user_id` int(11) DEFAULT NULL,
  `wp_user_type` enum('s','r') NOT NULL DEFAULT 's' COMMENT 's: sender, r: receiver',
  `wp_create_time` datetime DEFAULT NULL,
  `wp_message_text` blob COMMENT 'we put it blob note text to save emoji like ?',
  `wp_message_status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '-1: error, 0: pending, 1: sent, 2: delivered, 3: seen',
  `wp_message_cond` tinyint(4) NOT NULL DEFAULT '0' COMMENT '0: normal, 1: clear from chat list',
  `wp_message_error` varchar(500) NOT NULL DEFAULT '' COMMENT 'error message in case of error',
  `wp_delivered_time` datetime DEFAULT NULL,
  `wp_seen_time` datetime DEFAULT NULL,
  `wp_last_change` datetime DEFAULT NULL,
  `msg_api_id` int(11) DEFAULT NULL,
  `wp_reference_id` varchar(255) DEFAULT ''
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- --------------------------------------------------------

--
-- Table structure for table `wp_user`
--

CREATE TABLE `wp_user` (
  `wp_user_id` int(11) NOT NULL,
  `wp_user_name` varchar(255) NOT NULL DEFAULT '',
  `wp_user_number` varchar(50) NOT NULL DEFAULT '',
  `wp_user_image` varchar(255) NOT NULL DEFAULT '',
  `wp_last_message_id` int(11) DEFAULT NULL COMMENT 'last message send by him or sent to him',
  `wp_last_seen_time` datetime DEFAULT NULL,
  `msg_api_id` int(11) DEFAULT NULL,
  `wp_user_create_time` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

