DROP TABLE IF EXISTS `accrued_list`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `accrued_list`  AS  select `p`.`Accrued_Expense_ID` AS `Accrued_Expense_ID`,concat(`c`.`Currency_Symbol`,' ',`p`.`Expected_Amount`) AS `Expected_Amount`,concat(`c`.`Currency_Symbol`,' ',`p`.`Real_Amount`) AS `Real_Amount`,`p`.`Description` AS `Description`,`p`.`Start_Date` AS `Start_Date`,`p`.`End_Date` AS `End_Date`,`a`.`Account_Name` AS `Expense_Code`,`pa`.`Account_Name` AS `Accrued_Code`,`s`.`Supplier_Name` AS `Supplier_Name`,`c`.`Currency_Symbol` AS `Currency_Symbol`,if((`p`.`Real_Amount` > 0),1,0) AS `Status_ID`,`p`.`Is_Actual` AS `Is_Actual`,`p`.`current_year_id` AS `current_year_id`,`p`.`is_locked` AS `is_locked`,`p`.`is_pending` AS `is_pending`,`p`.`branch_id` AS `branch_id` from ((((`tbl_accounting_accrued_expenses` `p` left join `tbl_chart_of_accounts` `a` on((`a`.`Account_ID` = `p`.`Account_ID`))) left join `tbl_chart_of_accounts` `pa` on((`pa`.`Account_ID` = `p`.`Accrued_Account_ID`))) left join `tbl_stock_suppliers` `s` on((`s`.`Supplier_ID` = `p`.`Supplier_ID`))) left join `tbl_common_currency` `c` on((`c`.`Currency_ID` = `p`.`Currency_ID`))) where (`p`.`Status_ID` = 1) order by `p`.`Accrued_Expense_ID` desc ;

