--
-- Structure for view `balance_first`
--
DROP TABLE IF EXISTS `balance_first`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `balance_first`  AS  select sum(`t`.`Transaction_Amount`) AS `Credit`,(select 0) AS `Debit`,concat(`a`.`Account_Code`,`t`.`Currency_ID`) AS `unq`,`a`.`Account_Code` AS `Account_Code`,`t`.`Account_ID` AS `Account_ID`,`t`.`Currency_ID` AS `Currency_ID`,`a`.`main_id` AS `main_id`,`a`.`main_type` AS `main_type`,`a`.`sub_type` AS `sub_type` from (`tbl_accounting_transactions` `t` join `tbl_chart_of_accounts` `a` on((`a`.`Account_ID` = `t`.`Account_ID`))) where ((`t`.`Transaction_Type` = 'Credit') and (`t`.`current_year_id` = (select `tbl_common_current_year`.`current_year_id` from `tbl_common_current_year` where (`tbl_common_current_year`.`is_current` = 1)))) group by concat(`a`.`Account_Code`,`t`.`Currency_ID`) union select (select 0) AS `Credit`,sum(`t`.`Transaction_Amount`) AS `Debit`,concat(`a`.`Account_Code`,`t`.`Currency_ID`) AS `unq`,`a`.`Account_Code` AS `Account_Code`,`t`.`Account_ID` AS `Account_ID`,`t`.`Currency_ID` AS `Currency_ID`,`a`.`main_id` AS `main_id`,`a`.`main_type` AS `main_type`,`a`.`sub_type` AS `sub_type` from (`tbl_accounting_transactions` `t` join `tbl_chart_of_accounts` `a` on((`a`.`Account_ID` = `t`.`Account_ID`))) where ((`t`.`Transaction_Type` = 'Debit') and (`t`.`current_year_id` = (select `tbl_common_current_year`.`current_year_id` from `tbl_common_current_year` where (`tbl_common_current_year`.`is_current` = 1)))) group by concat(`a`.`Account_Code`,`t`.`Currency_ID`) ;

-- --------------------------------------------------------

