DROP TABLE IF EXISTS `balance_second`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `balance_second`  AS  select sum((`balance_first`.`Debit` - `balance_first`.`Credit`)) AS `result_t`,`balance_first`.`Account_Code` AS `Account_Code`,`balance_first`.`Account_ID` AS `Account_ID`,`balance_first`.`Currency_ID` AS `Currency_ID`,`balance_first`.`main_id` AS `main_id`,`balance_first`.`main_type` AS `main_type`,`balance_first`.`sub_type` AS `sub_type` from `balance_first` group by `balance_first`.`unq` ;

