al_vat_rate` AS `local_vat_rate`,`created_user`.`User_Full_Name` AS `created_full_name`,`modified_user`.`User_Full_Name` AS `modified_full_name`,concat_ws(' ',`sales`.`Employee_FirstName`,`sales`.`Employee_MiddleName`,`sales`.`Employee_LastName`) AS `salesman_full_name`,`r`.`return_approved_by` AS `return_approved_by`,`approved_user`.`User_Full_Name` AS `return_approved_full_name`,`r`.`return_is_approved` AS `return_is_approved`,`r`.`Depot_ID` AS `Depot_ID`,`w`.`Depot_Name` AS `Depot_Name`,`r`.`invoice_prefix` AS `return_prefix`,`r`.`Return_ID` AS `current_return_nb` from (((((((((`tbl_accounting_return_invoices` `r` left join `tbl_invoices` `i` on((`r`.`Invoice_Purchase_ID` = `i`.`Invoice_ID_Auto`))) join `tbl_common_currency` `c` on((`r`.`Currency_ID` = `c`.`Currency_ID`))) join `tbl_customers` `cs` on((`r`.`Person_ID` = `cs`.`Customer_ID`))) left join `tbl_accounting_jobs` `jobs` on((`jobs`.`job_id` = `r`.`job_id`))) join `tbl_common_users` `created_user` on((`created_user`.`User_ID` = `r`.`created_logged_id`))) left join `tbl_common_users` `modified_user` on((`modified_user`.`User_ID` = `r`.`Logged_ID`))) left join `tbl_hrm_employee` `sales` on((`sales`.`Employee_ID` = `r`.`Sales_ID`))) left join `tbl_common_users` `approved_user` on((`approved_user`.`User_ID` = `r`.`return_approved_by`))) join `tbl_stock_depot_warehouse` `w` on((`w`.`Depot_ID` = `r`.`Depot_ID`))) where (`r`.`Is_Customer_Invoice` = 1) order by `r`.`Return_Invoice_ID` desc ;

