CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `damaged_products`  AS  select `d`.`damage_id` AS `Damaged_ID`,`p`.`Product_ID` AS `ID`,`p`.`Product_Name` AS `Name`,`dg`.`Depot_ID` AS `Depot_ID`,`d`.`quantity` AS `Damaged_Quantity`,`d`.`current_quantity` AS `Item_Quantity_Current`,if((`d`.`detail_note` = ''),`dg`.`damage_note`,`d`.`detail_note`) AS `Damaged_Reason`,`dg`.`damage_date` AS `Adjust_Date`,`l`.`Depot_Name` AS `Depot_Name`,`dg`.`customer_id` AS `customer_id`,`cust`.`Customer_Name` AS `Customer_Name`,`d`.`unit_cost` AS `unit_cost`,(`d`.`unit_cost` * `d`.`quantity`) AS `total_cost`,`p`.`Category_ID` AS `Category_ID`,`p`.`brand_id` AS `brand_id`,`dg`.`app_damage_id` AS `app_damage_id`,`d`.`return_detail_id` AS `return_detail_id`,`u`.`UOM_Name` AS `UOM_Name`,`d`.`uom_id` AS `UOM_ID`,`t`.`damage_type_name` AS `damage_type_name`,`d`.`detail_id` AS `detail_id`,`dg`.`branch_id` AS `branch_id`,`p`.`main_supplier_id` AS `main_supplier_id`,`dg`.`damage_type_id` AS `damage_type_id`,`p`.`sub_supplier_id` AS `sub_supplier_id` from ((((((`tbl_damage_details` `d` join `tbl_damage` `dg` on((`dg`.`damage_id` = `d`.`damage_id`))) join `tbl_stock_products` `p` on((`p`.`Product_ID` = `d`.`product_id`))) join `tbl_stock_uom` `u` on((`u`.`UOM_ID` = `d`.`uom_id`))) join `tbl_stock_depot_warehouse` `l` on((`l`.`Depot_ID` = `dg`.`Depot_ID`))) left join `tbl_customers` `cust` on((`cust`.`Customer_ID` = `dg`.`customer_id`))) left join `tbl_damage_type` `t` on((`t`.`damage_type_id` = `dg`.`damage_type_id`))) ;

