--
-- Structure for view `datasource_productlist`
--
DROP TABLE IF EXISTS `datasource_productlist`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `datasource_productlist`  AS  select `p`.`main_supplier_id` AS `main_supplier_id`,`p`.`is_fixed_asset` AS `is_fixed_asset`,`p`.`Product_Code` AS `Product_Code`,`p`.`job_id` AS `job_id`,`p`.`assigned_employee_id` AS `assigned_employee_id`,`p`.`Product_Name` AS `Product_Name`,if(isnull(concat(`p`.`Product_Quantity`,' ',`uc`.`UOM_Name`)),`p`.`Product_Quantity`,concat(`p`.`Product_Quantity`,' ',`uc`.`UOM_Name`)) AS `Product_Quantity`,if((`p`.`default_view_uom_id` = 0),`uc`.`UOM_Name`,`dfvu`.`UOM_Name`) AS `def_view_uom_name`,if((`p`.`default_view_uom_id` = 0),`p`.`Product_Quantity`,(`p`.`Product_Quantity` / `p`.`default_view_rate`)) AS `Product_View_Quantity`,`p`.`Product_ID` AS `Product_ID`,`c`.`Cat_Name` AS `Cat_Name`,`p`.`Product_PLU` AS `Product_PLU`,`p`.`brand_id` AS `brand_id`,`br`.`brand_name` AS `brand_name`,`p`.`Status_ID` AS `Status_ID`,`u`.`Bar_Code` AS `Bar_Code`,`p`.`Category_ID` AS `Category_ID`,`p`.`Product_Quantity` AS `prod_quantity`,`p`.`product_second_code` AS `product_second_code`,`p`.`Product_Arabic_Name` AS `Product_Arabic_Name`,`p`.`family_id` AS `family_id`,`p`.`product_param1` AS `product_param1`,`p`.`disable_upload_web` AS `disable_upload_web`,`supp`.`Supplier_Name` AS `Supplier_Name`,`depot`.`Depot_Name` AS `Depot_Name`,`p`.`is_inspection_service` AS `is_inspection_service`,`u`.`additional_barcodes` AS `additional_barcodes`,`p`.`sub_supplier_id` AS `sub_supplier_id`,`sub_supp`.`Supplier_Name` AS `Sub_Supplier_Name`,`p`.`Product_Price` AS `fixed_price`,`p`.`branch_id` AS `branch_id` from (((((((((`tbl_stock_products` `p` join `tbl_product_cat` `c` on((`c`.`Cat_ID` = `p`.`Category_ID`))) left join `tbl_common_currency` `y` on((`y`.`Currency_ID` = `p`.`Currency_ID`))) join `tbl_stock_uom` `uc` on((`uc`.`UOM_ID` = `p`.`UOM_ID`))) left join `tbl_brand_products` `br` on((`br`.`brand_id` = `p`.`brand_id`))) left join `tbl_stock_suppliers` `supp` on((`supp`.`Supplier_ID` = `p`.`main_supplier_id`))) left join `tbl_stock_depot_warehouse` `depot` on((`depot`.`Depot_ID` = `p`.`default_depot_id`))) join `tbl_uom_conversions` `u` on(((`u`.`Product_ID` = `p`.`Product_ID`) and (`u`.`is_default` = 1)))) join `tbl_stock_uom` `dfvu` on((`dfvu`.`UOM_ID` = `p`.`default_view_uom_id`))) left join `tbl_stock_suppliers` `sub_supp` on((`sub_supp`.`Supplier_ID` = `p`.`sub_supplier_id`))) ;

