--
-- Structure for view `data_collecter_adjust`
--
DROP TABLE IF EXISTS `data_collecter_adjust`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `data_collecter_adjust`  AS  select `m`.`file_id` AS `file_id`,`c`.`Bar_Code` AS `Bar_Code`,`p`.`Product_Name` AS `Name`,sum((`a`.`quantity` * `c`.`conversion_amount`)) AS `Quantity`,`u`.`UOM_Name` AS `to_name`,`a`.`temp_id` AS `temp_id`,`p`.`Category_ID` AS `Category_ID`,`l`.`Product_Depot_ID` AS `Depot_ID`,`w`.`Depot_Name` AS `Depot`,`w`.`Depot_Code` AS `Code`,`a`.`Product_ID` AS `ID`,`a`.`UOM_ID` AS `UOM_ID`,if(isnull(`l`.`Product_Depot_Quantity`),0,`l`.`Product_Depot_Quantity`) AS `sys_qty`,`a`.`UOM_ID` AS `Product_UOM`,`p`.`is_expiry` AS `is_expiry`,`p`.`Status_ID` AS `Status_ID`,`p`.`default_view_uom_id` AS `default_view_uom_id`,`p`.`default_view_rate` AS `default_view_rate`,`dfvu`.`UOM_Name` AS `default_view_uom`,(sum((`a`.`quantity` * `c`.`conversion_amount`)) / `p`.`default_view_rate`) AS `Quantity_default`,(if(isnull(`l`.`Product_Depot_Quantity`),0,`l`.`Product_Depot_Quantity`) / `p`.`default_view_rate`) AS `sys_qty_default`,`p`.`is_lot` AS `is_lot`,`p`.`is_serial` AS `is_serial`,`p`.`main_supplier_id` AS `main_supplier_id`,`p`.`is_service` AS `is_service`,`cat`.`Cat_Name` AS `Cat_Name`,`p`.`product_param1` AS `product_param1`,`p`.`Product_Arabic_Name` AS `Product_Arabic_Name`,`p`.`sub_supplier_id` AS `sub_supplier_id`,(`l`.`depot_reserved_purchase_delivery_qty` / `p`.`default_view_rate`) AS `quantity_reserved_purchase_delivery_default`,`l`.`depot_reserved_purchase_delivery_qty` AS `reserved_purchase_delivery_qty` from ((((((((`tbl_app_temp_adjustments` `a` left join `tbl_uom_conversions` `c` on(((`a`.`UOM_ID` = `c`.`uom_from`) and (`a`.`Product_ID` = `c`.`Product_ID`)))) left join `tbl_stock_products` `p` on((`p`.`Product_ID` = `a`.`Product_ID`))) left join `tbl_stock_uom` `u` on((`u`.`UOM_ID` = `p`.`UOM_ID`))) join `tbl_stock_uom` `dfvu` on((`dfvu`.`UOM_ID` = `p`.`default_view_uom_id`))) left join `tbl_app_temp_main_adj` `m` on((`m`.`temp_main_id` = `a`.`temp_main_id`))) left join `tbl_stock_product_location` `l` on(((`l`.`Location_Product_ID` = `a`.`Product_ID`) and (`m`.`stock_id` = `l`.`Product_Depot_ID`)))) left join `tbl_stock_depot_warehouse` `w` on((`w`.`Depot_ID` = `l`.`Product_Depot_ID`))) join `tbl_product_cat` `cat` on((`cat`.`Cat_ID` = `p`.`Category_ID`))) group by `m`.`file_id`,`m`.`stock_id`,`a`.`Product_ID` ;

