DROP TABLE IF EXISTS `debit_list`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `debit_list`  AS  select `n`.`note_nb` AS `note_nb`,`n`.`Note_ID` AS `Note_ID`,`n`.`Supplier_Customer_ID` AS `Supplier_Customer_ID`,`n`.`Note_Date` AS `Note_Date`,`n`.`Currency_ID` AS `Currency_ID`,`n`.`Note_Amount` AS `Note_Amount`,`n`.`Note_Description` AS `Note_Description`,`n`.`Is_Debit_Note` AS `Is_Debit_Note`,`n`.`Logged_ID` AS `Logged_ID`,concat(`c`.`Currency_Symbol`,' ',`n`.`Note_Amount`) AS `Note_Amount_Curr`,`s`.`Supplier_Name` AS `Name`,`n`.`is_actual` AS `is_actual`,`n`.`current_year_id` AS `current_year_id`,`n`.`is_locked` AS `is_locked`,`n`.`is_pending` AS `is_pending`,`n`.`branch_id` AS `branch_id` from ((`tbl_accounting_debit_credit_note` `n` left join `tbl_common_currency` `c` on((`c`.`Currency_ID` = `n`.`Currency_ID`))) left join `tbl_stock_suppliers` `s` on((`s`.`Supplier_ID` = `n`.`Supplier_Customer_ID`))) where (`n`.`Is_Debit_Note` = 1) order by `n`.`Note_ID` desc ;

