--
-- Structure for view `delivered_sales_order`
--
DROP TABLE IF EXISTS `delivered_sales_order`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `delivered_sales_order`  AS  select `d`.`UOM_ID` AS `UOM_ID`,`u`.`UOM_Name` AS `UOM_Name`,`d`.`Item_ID` AS `Entry_ID`,`d`.`Sales_Order_ID` AS `Order_ID`,`s`.`Customer_Name` AS `Supplier_Name`,`s`.`Customer_ID` AS `Supplier_ID`,`o`.`Sales_Order_Date` AS `Order_Date`,`d`.`Product_ID` AS `Item_ID`,concat(`d`.`Item_Quantity_Current`,' ',`u`.`UOM_Name`) AS `Quantity`,if(isnull(`ur`.`UOM_Name`),concat(0,' ',`u`.`UOM_Name`),concat(`rd`.`Item_Quantity_Current`,' ',`ur`.`UOM_Name`)) AS `Product_Delivery_Quantity`,concat(if(isnull(`rd`.`Item_Quantity_Current`),`d`.`Item_Quantity_Current`,(`d`.`Item_Quantity_Current` - `rd`.`Item_Quantity_Current`)),' ',`u`.`UOM_Name`) AS `Remaining_Quantity`,`ps`.`Product_Code` AS `Code`,`ps`.`Product_Name` AS `Name`,`ps`.`Product_VAT` AS `VAT` from (((((((`tbl_garage_sales_order_details` `d` left join `tbl_stock_uom` `u` on((`d`.`UOM_ID` = `u`.`UOM_ID`))) left join `tbl_garage_sales_order` `o` on((`o`.`Sales_Order_ID` = `d`.`Sales_Order_ID`))) left join `tbl_stock_products` `ps` on((`d`.`Product_ID` = `ps`.`Product_ID`))) left join `tbl_inventory_delivery_report` `r` on(((`r`.`Order_ID` = `o`.`Sales_Order_ID`) and (`r`.`Is_Customer_Invoice` = 1)))) left join `tbl_inventory_delivery_report_items` `rd` on((`rd`.`Delivery_Report_ID` = `r`.`Delivery_Report_ID`))) left join `tbl_stock_uom` `ur` on((`rd`.`UOM_ID` = `ur`.`UOM_ID`))) left join `tbl_customers` `s` on((`s`.`Customer_ID` = `o`.`Customer_ID`))) ;

