CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `delivery_employees`  AS  select `emp`.`Employee_ID` AS `Employee_ID`,`emp`.`Employee_FirstName` AS `Employee_FirstName`,`emp`.`Employee_MiddleName` AS `Employee_MiddleName`,`emp`.`Employee_LastName` AS `Employee_LastName`,concat_ws(' ',`emp`.`Employee_FirstName`,`emp`.`Employee_MiddleName`,`emp`.`Employee_LastName`) AS `employee_full_name`,`emp`.`employee_mother_name` AS `employee_mother_name`,`emp`.`employee_mother_last_name` AS `employee_mother_last_name`,`emp`.`Employee_DOB` AS `Employee_DOB`,`emp`.`Employee_HomePhone` AS `Employee_HomePhone`,`emp`.`Employee_MobilePhone` AS `Employee_MobilePhone`,`emp`.`Employee_Email` AS `Employee_Email`,`emp`.`Merital_Status_ID` AS `Merital_Status_ID`,`emp`.`employee_neighborhood` AS `employee_neighborhood`,`emp`.`Employee_StreetAddress1` AS `Employee_StreetAddress1`,`emp`.`employee_building` AS `employee_building`,`emp`.`employee_floor` AS `employee_floor`,`emp`.`Employee_City` AS `Employee_City`,`emp`.`Employee_Country` AS `Employee_Country`,`emp`.`Employee_Nationality` AS `Employee_Nationality`,`emp`.`Employee_Wife_Name` AS `Employee_Wife_Name`,`emp`.`job_id` AS `job_id`,`emp`.`date_created` AS `date_created`,`emp`.`date_modified` AS `date_modified`,`emp`.`employee_nb_children` AS `employee_nb_children`,`emp`.`penalty_points_record` AS `penalty_points_record`,`nationality`.`Nationality_Name` AS `Nationality_Name`,`jobs`.`Job_Name` AS `Job_Name`,`country`.`Country_Name` AS `Country_Name`,`city`.`Name` AS `Name`,`users`.`User_Name` AS `User_Name`,`users`.`is_app` AS `is_app`,`users`.`Role_ID` AS `Role_ID` from (((((`tbl_hrm_employee` `emp` join `tbl_hrm_nationalities` `nationality` on((`nationality`.`Nationality_ID` = `emp`.`Employee_Nationality`))) join `tbl_hrm_jobs` `jobs` on((`jobs`.`Job_ID` = `emp`.`job_id`))) join `tbl_all_countries` `country` on((`country`.`Country_ID` = `emp`.`Employee_Country`))) join `tbl_all_cities` `city` on((`city`.`ID` = `emp`.`Employee_City`))) join `tbl_common_users` `users` on(((`users`.`origin_id` = `emp`.`Employee_ID`) and (`users`.`origin` = 1)))) ;

