DROP TABLE IF EXISTS `delivery_list`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `delivery_list`  AS  select `invoice`.`Invoice_ID_Auto` AS `Invoice_ID_Auto`,`invoice`.`Invoice_Net_Total` AS `Invoice_Net_Total`,`customer`.`customer_id` AS `customer_id`,`customer`.`customer_name` AS `customer_name`,`customer`.`customer_phone` AS `customer_phone`,`address`.`address_name` AS `address_name`,`invoice`.`Is_Closed` AS `Is_Closed`,`invoice`.`is_committed` AS `is_committed`,`invoice`.`invoice_type` AS `invoice_type` from ((`tbl_invoices` `invoice` left join `tbl_pos_customers` `customer` on((`invoice`.`pos_customer_id` = `customer`.`customer_id`))) left join `tbl_customer_address` `address` on((`invoice`.`address_id` = `address`.`address_id`))) where ((`invoice`.`is_app` = 1) and (`invoice`.`app_status` = 0)) ;

