--
-- Structure for view `delivery_notes`
--
DROP TABLE IF EXISTS `delivery_notes`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `delivery_notes`  AS  select `r`.`Delivery_Report_ID` AS `Delivery_Report_ID`,`r`.`Person_ID` AS `Person_ID`,`r`.`Delivery_Report_Date` AS `Delivery_Report_Date`,`r`.`Is_Customer_Invoice` AS `Is_Customer_Invoice`,`r`.`Order_ID` AS `Order_ID`,`r`.`delivery_nb` AS `delivery_nb`,`r`.`date_created` AS `date_created`,`r`.`date_time` AS `date_time`,`r`.`Logged_ID` AS `Logged_ID`,`r`.`created_logged_id` AS `created_logged_id`,`r`.`current_year_id` AS `current_year_id`,`r`.`Depot_ID` AS `Depot_ID`,`r`.`delivery_note` AS `delivery_note`,`r`.`branch_id` AS `branch_id`,`r`.`job_id` AS `job_id`,`r`.`project_id` AS `project_id`,`r`.`is_actual` AS `is_actual`,`j`.`job_name` AS `job_name`,`p`.`project_name` AS `project_name`,if((`r`.`Is_Customer_Invoice` = 1),`c`.`Customer_Name`,`s`.`Supplier_Name`) AS `Person_Name`,`r`.`invoice_type_id` AS `invoice_type_id`,`r`.`is_locked` AS `is_locked`,`r`.`is_printed` AS `is_printed`,`orders`.`Order_ID_Auto` AS `Order_ID_Auto`,`orders`.`sale_prefix` AS `sale_prefix`,`r`.`mate_ids` AS `mate_ids`,`r`.`is_received` AS `is_received`,`r`.`delivery_ref` AS `delivery_ref`,`r`.`is_partially_delivered` AS `is_partially_delivered`,if(isnull(`r`.`delivery_status`),'',if((`r`.`delivery_status` = 1),'Installation','Finished')) AS `delivery_status_name`,`r`.`delivery_status` AS `delivery_status`,`r`.`delivery_prefix` AS `delivery_prefix`,concat_ws('',`r`.`delivery_prefix`,`r`.`delivery_nb`) AS `delivery_prefix_nb` from (((((`tbl_inventory_delivery_report` `r` left join `tbl_customers` `c` on(((`c`.`Customer_ID` = `r`.`Person_ID`) and (`r`.`Is_Customer_Invoice` = 1)))) left join `tbl_stock_suppliers` `s` on((`s`.`Supplier_ID` = `r`.`Person_ID`))) left join `tbl_accounting_jobs` `j` on((`j`.`job_id` = `r`.`job_id`))) left join `tbl_projects` `p` on((`p`.`project_id` = `r`.`project_id`))) left join `tbl_purchase_order` `orders` on((`orders`.`Order_ID` = `r`.`Order_ID`))) order by `r`.`Delivery_Report_Date` desc,`r`.`delivery_nb` desc ;

