--
-- Structure for view `delivery_orders`
--
DROP TABLE IF EXISTS `delivery_orders`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `delivery_orders`  AS  select `orders`.`order_id` AS `order_id`,`orders`.`order_nb` AS `order_nb`,`orders`.`supplier_id` AS `supplier_id`,`orders`.`order_status_id` AS `order_status_id`,`orders`.`order_quantity` AS `order_quantity`,`orders`.`order_description` AS `order_description`,`orders`.`assigned_driver_id` AS `assigned_driver_id`,`orders`.`ten_percent_value` AS `ten_percent_value`,`orders`.`delivery_fees` AS `delivery_fees`,`orders`.`order_total` AS `order_total`,`orders`.`currency_id` AS `currency_id`,`orders`.`current_rate` AS `current_rate`,`orders`.`second_currency_rate` AS `second_currency_rate`,`orders`.`is_return` AS `is_return`,`orders`.`is_bill_shipper_receiver` AS `is_bill_shipper_receiver`,`orders`.`is_picture_required` AS `is_picture_required`,`orders`.`is_closed_parcel` AS `is_closed_parcel`,`orders`.`need_package` AS `need_package`,`orders`.`is_secret_sender` AS `is_secret_sender`,`orders`.`customer_id` AS `customer_id`,`orders`.`appointment_date` AS `appointment_date`,`orders`.`reason_id` AS `reason_id`,`supplier`.`Supplier_Name` AS `client_name`,`supplier`.`Supplier_Work_Phone` AS `client_landline`,`supplier`.`Supplier_Mobile` AS `client_mobile`,`supplier`.`supplier_neighborhood` AS `client_neighborhood`,`supplier`.`supplier_street` AS `client_street`,`supplier`.`supplier_building` AS `client_building`,`supplier`.`supplier_floor` AS `client_floor`,`currency`.`Currency_Name` AS `Currency_Name`,`currency`.`Currency_Symbol` AS `Currency_Symbol`,`order_status`.`order_status_title` AS `order_status_title`,`city`.`Name` AS `client_city_name`,concat_ws(' ',`emp`.`Employee_FirstName`,`emp`.`Employee_MiddleName`,`emp`.`Employee_LastName`) AS `driver_full_name`,`cust`.`Customer_Name` AS `Customer_Name`,`cust`.`Customer_Mobile` AS `Customer_Mobile`,`cust`.`Customer_Email` AS `Customer_Email`,`cust`.`customer_neighborhood` AS `customer_neighborhood`,`cust`.`customer_street` AS `customer_street`,`cust`.`customer_building` AS `customer_building`,`cust`.`customer_floor` AS `customer_floor`,`cust_city`.`Name` AS `customer_city_name`,`orders`.`depot_id` AS `depot_id`,`orders`.`order_date` AS `order_date`,`order_status`.`order_status_color` AS `order_status_color`,`orders`.`order_type` AS `order_type`,`orders`.`date_assigned_pickup` AS `date_assigned_pickup`,`cust`.`Customer_City_ID` AS `Customer_City_ID`,`cust`.`Customer_Country_ID` AS `Customer_Country_ID`,if((`orders`.`order_type` = 0),'normal',if((`orders`.`order_type` = 1),'Peer to peer','On spot delivery')) AS `order_type_name`,`orders`.`payment_account_id` AS `payment_account_id`,`orders`.`paid_amount` AS `paid_amount`,`accounts`.`Account_Name` AS `payment_account_name`,`cust`.`Customer_Address` AS `Customer_Address`,`orders`.`order_customer_detail` AS `order_customer_detail` from ((((((((`tbl_delivery_order` `orders` join `tbl_stock_suppliers` `supplier` on((`supplier`.`Supplier_ID` = `orders`.`supplier_id`))) join `tbl_delivery_order_status` `order_status` on((`order_status`.`order_status_id` = `orders`.`order_status_id`))) join `tbl_common_currency` `currency` on((`currency`.`Currency_ID` = `orders`.`currency_id`))) join `tbl_customers` `cust` on((`cust`.`Customer_ID` = `orders`.`customer_id`))) join `tbl_all_cities` `city` on((`city`.`ID` = `supplier`.`City_ID`))) left join `tbl_hrm_employee` `emp` on((`emp`.`Employee_ID` = `orders`.`assigned_driver_id`))) join `tbl_all_cities` `cust_city` on((`cust_city`.`ID` = `cust`.`Customer_City_ID`))) left join `tbl_chart_of_accounts` `accounts` on((`accounts`.`Account_ID` = `orders`.`payment_account_id`))) ;

