n_Product_ID` = `p`.`Product_ID`))) join `uom_conversions` `u` on(((`p`.`Product_ID` = `u`.`Product_ID`) and (if((`p`.`default_view_uom_id` = 0),`p`.`UOM_ID`,`p`.`default_view_uom_id`) = `u`.`uom_from`)))) left join `tbl_brand_products` `b` on((`b`.`brand_id` = `p`.`brand_id`))) join `tbl_stock_uom` `def_uom` on((`def_uom`.`UOM_ID` = `p`.`UOM_ID`))) join `tbl_stock_uom` `dfvu` on((`dfvu`.`UOM_ID` = `p`.`default_view_uom_id`))) join `tbl_product_cat` `cat` on((`cat`.`Cat_ID` = `p`.`Category_ID`))) join `tbl_uom_conversions` `ud` on(((`ud`.`uom_from` = `p`.`UOM_ID`) and (`ud`.`Product_ID` = `p`.`Product_ID`)))) group by concat(`u`.`Product_ID`,'_',`d`.`Depot_ID`) ;

