CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `due_date_purchase`  AS  select `i`.`Supplier_ID` AS `Person_ID`,`i`.`Purchase_ID_Auto` AS `Inv_Pur_ID_Auto`,`i`.`Purchase_ID` AS `Inv_Pur_ID`,`i`.`Purchase_Net_Total` AS `Total`,`i`.`Purchase_Due_Date` AS `Due_Date`,`c`.`Currency_Symbol` AS `Currency_Symbol`,(`i`.`Purchase_Paid_Amount` + `i`.`Payment_Paid_Amount`) AS `Paid_Amount`,`cu`.`Supplier_Name` AS `Name`,`cu`.`Supplier_Email` AS `Email`,`cu`.`Supplier_Phone` AS `Phone`,`cu`.`Supplier_Company` AS `Company`,`i`.`Purchase_Date` AS `Date`,(((((`i`.`Purchase_Net_Total` + `i`.`Purchase_Shipping`) - `i`.`Purchase_Paid_Amount`) - `i`.`Payment_Paid_Amount`) - `i`.`Return_Purchase_Total`) + `i`.`return_paid_amount`) AS `remaining_amount`,`i`.`current_rate` AS `current_rate`,`i`.`second_currency_rate` AS `second_currency_rate`,(`i`.`Return_Purchase_Total` - `i`.`return_paid_amount`) AS `net_return`,`i`.`Purchase_Shipping` AS `shipping`,`i`.`extra_cost` AS `extra_cost`,((`i`.`Purchase_Net_Total` + `i`.`Purchase_Shipping`) + `i`.`extra_cost`) AS `net_total`,`i`.`ship_bill_nb` AS `ship_bill_nb`,`i`.`ship_date` AS `ship_date`,`i`.`branch_id` AS `branch_id`,`i`.`disable_qty` AS `disable_qty`,`i`.`invoice_prefix` AS `invoice_prefix`,`i`.`Purchase_ID` AS `current_invoice_nb` from ((`tbl_inventory_purchases` `i` join `tbl_common_currency` `c` on((`i`.`Currency_ID` = `c`.`Currency_ID`))) join `tbl_stock_suppliers` `cu` on((`i`.`Supplier_ID` = `cu`.`Supplier_ID`))) where ((`i`.`Purchase_Net_Total` - `i`.`Return_Purchase_Total`) > (`i`.`Purchase_Paid_Amount` + `i`.`Payment_Paid_Amount`)) order by `i`.`Purchase_Due_Date` ;

