tted`,`i`.`invoice_type` AS `invoice_type`,`i`.`is_actual` AS `is_actual`,`tabl`.`status_id` AS `table_status_id` from (((`tbl_invoices` `i` left join `tbl_customers` `c` on((`i`.`Customer_ID` = `c`.`Customer_ID`))) left join `tbl_table` `tabl` on((`i`.`table_id` = `tabl`.`table_id`))) join `tbl_common_currency` `cc` on((`cc`.`Currency_ID` = `i`.`Invoice_Currency`))) order by `i`.`Invoice_Status` ;

