ay_paid_amount`,(`e`.`Purchase_Paid_Amount` + `e`.`Payment_Paid_Amount`) AS `total_paid_amount`,(((((`e`.`Purchase_Net_Total` + `e`.`Purchase_Shipping`) - `e`.`Purchase_Paid_Amount`) - `e`.`Payment_Paid_Amount`) - `e`.`Return_Purchase_Total`) + `e`.`return_paid_amount`) AS `remaining_amount`,`e`.`invoice_type_id` AS `invoice_type_id`,`e`.`is_locked` AS `is_locked`,`e`.`person_id` AS `person`,`e`.`is_pending` AS `is_pending`,`e`.`Purchase_ID` AS `Purchase_ID`,`e`.`job_id` AS `job_id`,ifnull(`j`.`job_name`,'') AS `job_name`,`e`.`created_logged_id` AS `created_logged_id`,`e`.`additional_cost_percent` AS `additional_cost_percent`,`e`.`dynamic_type_id` AS `dynamic_type_id`,`s`.`Supplier_CR` AS `Supplier_CR`,`e`.`discount_amount` AS `discount_amount`,`e`.`bl_date` AS `bl_date`,`e`.`bl_number` AS `bl_number`,`e`.`boe_number` AS `boe_number`,`e`.`delivery_date` AS `delivery_date`,`e`.`order_id` AS `order_id`,`p`.`Order_ID_Auto` AS `related_po_nb`,`e`.`adjusted_prices` AS `adjusted_prices` from ((((`tbl_inventory_purchases` `e` join `tbl_stock_suppliers` `s` on((`s`.`Supplier_ID` = `e`.`Supplier_ID`))) join `tbl_common_currency` `cu` on((`cu`.`Currency_ID` = `e`.`Currency_ID`))) left join `tbl_accounting_jobs` `j` on((`j`.`job_id` = `e`.`job_id`))) left join `tbl_purchase_order` `p` on((`p`.`Order_ID` = `e`.`order_id`))) order by `e`.`Purchase_ID_Auto` desc ;

