DROP TABLE IF EXISTS `purchase_returned_list`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `purchase_returned_list`  AS  select `p`.`current_year_id` AS `current_year_id`,`p`.`Auto_ID` AS `Auto_ID`,`r`.`Total_Returned_Price` AS `Total`,`r`.`Return_Date` AS `Return_Date`,`p`.`UOM_ID` AS `UOM_ID`,`p`.`UOM_Name` AS `UOM_Name`,`p`.`Product_ID` AS `Product_ID`,`p`.`Inv_Pur_ID` AS `Inv_Pur_ID`,`p`.`Net_Total` AS `Net_Total`,`p`.`Main_Discount` AS `Main_Discount`,`p`.`Person_Name` AS `Person_Name`,`p`.`Person_ID` AS `Person_ID`,`p`.`Inv_Pur_Date` AS `Inv_Pur_Date`,`p`.`Currency_ID` AS `Currency_ID`,`p`.`Quantity` AS `Quantity`,`p`.`Code` AS `Code`,`p`.`Name` AS `Name`,`p`.`Item_VAT` AS `Item_VAT`,`p`.`Item_Discount` AS `Item_Discount`,`p`.`Currency_Symbol` AS `Currency_Symbol`,`p`.`Item_Price` AS `Item_Price`,`p`.`Item_Quantity_Current` AS `Item_Quantity_Current`,`p`.`Item_Quantity` AS `Item_Quantity`,if(isnull((`p`.`Item_Quantity_Current` - `r`.`Item_Quantity_Current`)),`p`.`Item_Quantity_Current`,(`p`.`Item_Quantity_Current` - `r`.`Item_Quantity_Current`)) AS `Remain_Main`,concat(if(isnull((`p`.`Item_Quantity_Current` - `r`.`Item_Quantity_Current`)),`p`.`Item_Quantity_Current`,(`p`.`Item_Quantity_Current` - `r`.`Item_Quantity_Current`)),' ',`p`.`UOM_Name`) AS `Remaining_Quantity`,((`p`.`Item_Price` * if(isnull((`p`.`Item_Quantity` - `r`.`Return_Product_Quantity`)),`p`.`Item_Quantity`,(`p`.`Item_Quantity` - `r`.`Return_Product_Quantity`))) - ((`p`.`Item_Price` * if(isnull((`p`.`Item_Quantity` - `r`.`Return_Product_Quantity`)),`p`.`Item_Quantity`,(`p`.`Item_Quantity` - `r`.`Return_Product_Quantity`))) * (`p`.`Item_Discount` / 100))) AS `Total_Item_Price`,if(isnull(concat(`r`.`Item_Quantity_Current`,' ',`r`.`UOM_Name`)),concat(0,' ',`p`.`UOM_Name`),convert(concat(`r`.`Item_Quantity_Current`,' ',`r`.`UOM_Name`) using utf8)) AS `Product_Return_Quantity`,if(isnull((`r`.`Return_Product_Quantity` * `p`.`Item_Price`)),0,(`r`.`Return_Product_Quantity` * `p`.`Item_Price`)) AS `Total_Item_Returned_Price` from (`purchase_main_detailed` `p` left join `returned_main_detailed` `r` on(((convert(`p`.`unq` using utf8) = convert(`r`.`unq` using utf8)) and (`r`.`Is_Customer_Invoice` = 0)))) ;

