DROP TABLE IF EXISTS `purchase_returned_products`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `purchase_returned_products`  AS  select `d`.`UOM_ID` AS `UOM_ID`,`u`.`UOM_Name` AS `UOM_Name`,`d`.`Product_ID` AS `Product_ID`,`o`.`Purchase_ID` AS `Inv_Pur_ID`,(`o`.`Purchase_Net_Total` - `o`.`Return_Purchase_Total`) AS `Net_Total`,`o`.`Purchase_Discount` AS `Main_Discount`,`s`.`Supplier_Name` AS `Person_Name`,`s`.`Supplier_ID` AS `Person_ID`,`o`.`Purchase_Date` AS `Inv_Pur_Date`,`o`.`Currency_ID` AS `Currency_ID`,concat(`d`.`Item_Quantity_Current`,' ',`u`.`UOM_Name`) AS `Quantity`,if(isnull(concat(`rd`.`Item_Quantity_Current`,' ',`ur`.`UOM_Name`)),concat(0,' ',`u`.`UOM_Name`),concat(`rd`.`Item_Quantity_Current`,' ',`ur`.`UOM_Name`)) AS `Product_Return_Quantity`,if(isnull((`d`.`Item_Quantity_Current` - `rd`.`Item_Quantity_Current`)),`d`.`Item_Quantity_Current`,(`d`.`Item_Quantity_Current` - `rd`.`Item_Quantity_Current`)) AS `Remain_Main`,concat(if(isnull((`d`.`Item_Quantity_Current` - `rd`.`Item_Quantity_Current`)),`d`.`Item_Quantity_Current`,(`d`.`Item_Quantity_Current` - `rd`.`Item_Quantity_Current`)),' ',`u`.`UOM_Name`) AS `Remaining_Quantity`,`ps`.`Product_Code` AS `Code`,`ps`.`Product_Name` AS `Name`,`ps`.`Product_VAT` AS `Item_VAT`,`d`.`Item_Discount` AS `Item_Discount`,`cu`.`Currency_Symbol` AS `Currency_Symbol`,(`d`.`Item_Price` * (`d`.`Item_Quantity` / `d`.`Item_Quantity_Current`)) AS `Item_Price`,((`d`.`Item_Price` * if(isnull((`d`.`Item_Quantity` - `rd`.`Return_Product_Quantity`)),`d`.`Item_Quantity`,(`d`.`Item_Quantity` - `rd`.`Return_Product_Quantity`))) - ((`d`.`Item_Price` * if(isnull((`d`.`Item_Quantity` - `rd`.`Return_Product_Quantity`)),`d`.`Item_Quantity`,(`d`.`Item_Quantity` - `rd`.`Return_Product_Quantity`))) * (`d`.`Item_Discount` / 100))) AS `Total_Item_Price` from ((((((((`tbl_inventory_purchase_items` `d` left join `tbl_stock_uom` `u` on((`d`.`UOM_ID` = `u`.`UOM_ID`))) left join `tbl_inventory_purchases` `o` on((`o`.`Purchase_ID_Auto` = `d`.`Purchase_ID_Auto`))) left join `tbl_common_currency` `cu` on((`cu`.`Currency_ID` = `o`.`Currency_ID`))) left join `tbl_stock_products` `ps` on((`d`.`Product_ID` = `ps`.`Product_ID`))) left join `tbl_accounting_return_invoices` `r` on(((`r`.`Invoice_Purchase_ID` = `o`.`Purchase_ID`) and (`r`.`Is_Customer_Invoice` = 0)))) left join `tbl_accounting_return_items` `rd` on(((`d`.`Product_ID` = `rd`.`Product_ID`) and (`rd`.`Return_Invoice_ID` = `r`.`Return_Invoice_ID`)))) left join `tbl_stock_uom` `ur` on((`rd`.`UOM_ID` = `ur`.`UOM_ID`))) left join `tbl_stock_suppliers` `s` on((`s`.`Supplier_ID` = `o`.`Supplier_ID`))) where (`o`.`current_year_id` = (select `tbl_common_current_year_actual`.`current_year_id` from `tbl_common_current_year_actual` where (`tbl_common_current_year_actual`.`is_current` = 1))) ;

