CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `sales_invoice_list`  AS  select `orders`.`Order_ID` AS `Order_ID`,`e`.`order_id` AS `order_id_invoice`,`orders`.`Order_ID_Auto` AS `Order_nb`,`e`.`is_actual` AS `is_actual`,`e`.`sales_purchase_id` AS `sales_purchase_id`,`e`.`Invoice_Status` AS `Invoice_Status`,`e`.`Is_Delivery` AS `is_delivery`,`e`.`Delivery_Time` AS `Delivery_Time`,`e`.`date_time` AS `date_time`,`e`.`Invoice_ID_Auto` AS `ID_Auto`,concat(`e`.`invoice_prefix`,`e`.`Invoice_ID`) AS `ID`,`e`.`Invoice_ID` AS `current_invoice_nb`,`s`.`Customer_Name` AS `Name`,`s`.`Customer_Mobile` AS `customer_mobile`,`e`.`Invoice_Date` AS `Date`,`e`.`Invoice_Due_Date` AS `Due_Date`,`e`.`Is_Closed` AS `Is_Closed`,concat(round(`e`.`Invoice_VAT`,2),' ',`cu`.`Currency_Symbol`) AS `VAT`,concat(round(`e`.`Invoice_Sub_Total`,2),' ',`cu`.`Currency_Symbol`) AS `SubTotal`,concat(round(`e`.`Invoice_Net_Total`,2),' ',`cu`.`Currency_Symbol`) AS `NetTotal`,`s`.`Customer_ID` AS `Person_ID`,`e`.`cash_amount` AS `cash_amount`,`e`.`momo_paid_amount` AS `momo_paid_amount`,`e`.`eft_paid_amount` AS `eft_paid_amount`,`e`.`check_amount` AS `check_amount`,`e`.`card_amount` AS `card_amount`,`e`.`current_year_id` AS `current_year_id`,`e`.`Logged_ID` AS `Logged_ID`,`e`.`is_app` AS `is_app`,`s`.`Customer_Country_ID` AS `Country_ID`,`e`.`date_created` AS `date_created`,`e`.`branch_id` AS `branch_id`,`e`.`pos_customer_id` AS `pos_customer_id`,`e`.`table_id` AS `table_id`,`e`.`invoice_prefix` AS `invoice_prefix`,0 AS `purchase_type_id`,`e`.`is_committed` AS `is_committed`,`e`.`invoice_type` AS `invoice_type`,`e`.`is_branch_transfer` AS `is_branch_transfer`,`e`.`invoice_app_id` AS `invoice_app_id`,`e`.`exchange_id` AS `exchange_id`,`e`.`is_printed_invoice` AS `is_printed_invoice`,(`e`.`Invoice_Net_Total` * `e`.`current_rate`) AS `local_net_total`,`e`.`shipping_company_id` AS `shipping_company_id`,`ship_comp`.`shipping_company_name` AS `shipping_company_name`,`e`.`Invoice_Sub_Total` AS `current_sub_total`,(`e`.`Invoice_Net_Total` + if((`e`.`shipping_on_self` = 1),0,if((`e`.`shipping_currency_id` = `e`.`Invoice_Currency`),`e`.`Invoice_Shipping`,((`e`.`Invoice_Shipping` * `e`.`shipping_current_rate`) / `e`.`current_rate`)))) AS `current_net_total`,((`e`.`Invoice_Net_Total` + if((`e`.`shipping_on_self` = 1),0,if((`e`.`shipping_currency_id` = `e`.`Invoice_Currency`),`e`.`Invoice_Shipping`,((`e`.`Invoice_Shipping` * `e`.`shipping_current_rate`) / `e`.`current_rate`)))) * `e`.`current_rate`) AS `current_net_total_in_local`,`e`.`Invoice_VAT` AS `current_vat`,`cu`.`Currency_Symbol` AS `Currency_Symbol`,`e`.`is_main_transfer` AS `is_main_transfer`,`e`.`subscription_fees_id` AS `subscription_fees_id`,`e`.`Invoice_Shipping` AS `shipping_fees`,`s`.`customer_group_id` AS `current_group_id`,`s`.`customer_class_id` AS `current_class_id`,`e`.`customer_branch_id` AS `customer_branch_id`,`e`.`Sales_ID` AS `Sales_ID`,`e`.`Depot_ID` AS `Depot_ID`,`e`.`shipping_status_id` AS `shipping_status_id`,`e`.`invoice_type_id` AS `invoice_type_id`,`e`.`reason_id` AS `reason_id`,`e`.`invoice_user_reference` AS `user_ref`,`e`.`Return_Invoice_Total` AS `return_total`,`e`.`return_paid_amount` AS `return_paid_amount`,`e`.`return_ids` AS `return_ids`,`e`.`ticketing_id` AS `ticketing_id`,`e`.`Invoice_Description` AS `inv_desc`,`e`.`Invoice_Paid_Amount` AS `inv_paid_amount`,`e`.`Payment_Paid_Amount` AS `pay_paid_amount`,(`e`.`Invoice_Paid_Amount` + `e`.`Payment_Paid_Amount`) AS `total_paid_amount`,(((((`e`.`Invoice_Net_Total` + if((`e`.`shipping_on_self` = 1),0,if((`e`.`shipping_currency_id` = `e`.`Invoice_Currency`),`e`.`Invoice_Shipping`,((`e`.`Invoice_Shipping` * `e`.`shipping_current_rate`) / `e`.`current_rate`)))) - `e`.`Invoice_Paid_Amount`) - `e`.`Payment_Paid_Amount`) - `e`.`Return_Invoice_Total`) + `e`.`return_paid_amount`) AS `remaining_amount`,`e`.`is_locked` AS `is_locked`,`e`.`driver_id` AS `driver_id`,`e`.`Invoice_ID` AS `Invoice_ID`,`e`.`job_id` AS `job_id`,ifnull(`j`.`job_name`,'') AS `job_name`,`users`.`User_Full_Name` AS `User_Full_Name`,`e`.`created_logged_id` AS `created_logged_id`,`e`.`customer_name_alias` AS `customer_name_alias`,`e`.`customer_address_alias` AS `customer_address_alias`,`e`.`Invoice_Currency` AS `Invoice_Currency`,`s`.`Customer_Address` AS `Customer_Address`,concat(`cpy_inv`.`invoice_prefix`,`cpy_inv`.`Invoice_ID`) AS `source_actual_invoice_nb`,concat_ws('',`emp`.`Employee_FirstName`,' ',`emp`.`Employee_MiddleName`,' ',`emp`.`Employee_LastName`) AS `salesman_name`,`e`.`Invoice_Note` AS `Invoice_Note`,`e`.`is_zatca_reported` AS `is_zatca_reported`,`e`.`Invoice_Net_Total` AS `Invoice_Net_Total`,`s`.`tax_number` AS `buyer_vat_number`,`s`.`Customer_CR` AS `Customer_CR`,`city`.`Name` AS `customer_city_name`,`e`.`rpay_paid_amount` AS `rpay_paid_amount`,`driver`.`driver_name` AS `driver_name`,`s`.`tax_number` AS `tax_number` from ((((((((((`tbl_invoices` `e` join `tbl_customers` `s` on((`s`.`Customer_ID` = `e`.`Customer_ID`))) join `tbl_common_currency` `cu` on((`cu`.`Currency_ID` = `e`.`Invoice_Currency`))) left join `tbl_shipping_company` `ship_comp` on((`ship_comp`.`shipping_company_id` = `e`.`shipping_company_id`))) left join `tbl_accounting_jobs` `j` on((`j`.`job_id` = `e`.`job_id`))) join `tbl_common_users` `users` on((`users`.`User_ID` = `e`.`created_logged_id`))) left join `tbl_purchase_order` `orders` on((`orders`.`Order_ID` = `e`.`order_id`))) left join `tbl_invoices` `cpy_inv` on((`cpy_inv`.`Invoice_ID_Auto` = `e`.`cpyact_invoice_id`))) left join `tbl_hrm_employee` `emp` on((`emp`.`Employee_ID` = `e`.`Sales_ID`))) left join `tbl_all_cities` `city` on((`city`.`ID` = `s`.`Customer_City_ID`))) left join `tbl_drivers` `driver` on((`driver`.`driver_id` = `e`.`driver_id`))) order by `e`.`Invoice_ID_Auto` desc ;

