CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `transactions_info`  AS  select `a`.`is_actual` AS `is_actual`,`a`.`main_id` AS `main_id`,`a`.`main_type` AS `main_type`,`u`.`User_Name` AS `User_Name`,`a`.`Transaction_ID` AS `Transaction_ID`,`a`.`Account_ID` AS `Account_ID`,`ca`.`Account_Name` AS `Account_Name`,`a`.`JV_ID` AS `JV_ID`,if((`a`.`is_actual` = 1),concat('Act. ',`a`.`JV_ID`),`a`.`JV_ID`) AS `jv_nb`,`a`.`Transaction_Reference` AS `Transaction_Reference`,`a`.`user_ref` AS `user_ref`,`ca`.`Account_Code` AS `Transaction_Account`,`a`.`Transaction_Type` AS `Transaction_Type`,`a`.`Transaction_Amount` AS `Transaction_Amount`,`a`.`Currency_ID` AS `Currency_ID`,`a`.`Transaction_Date` AS `Transaction_Date`,`a`.`Transaction_Description` AS `Transaction_Description`,`a`.`Logged_ID` AS `Logged_ID`,`a`.`Exchange_Rate_ID` AS `Exchange_Rate_ID`,`a`.`Current_Ex_Rate` AS `Current_Ex_Rate`,`a`.`current_year_id` AS `current_year_id`,`c`.`Currency_Symbol` AS `Currency_Symbol`,`a`.`branch_id` AS `branch_id`,`b`.`branch_name` AS `branch_name`,`a`.`job_id` AS `job_id`,`aj`.`job_name` AS `job_name`,`a`.`subtype` AS `subtype`,`a`.`due_date` AS `due_date`,`ca`.`job_ids` AS `job_ids`,`ca`.`job_required` AS `job_required`,`a`.`second_currency_rate` AS `second_currency_rate`,(`a`.`Transaction_Amount` * `a`.`Current_Ex_Rate`) AS `local_amount`,(`a`.`Transaction_Amount` * `a`.`second_currency_rate`) AS `second_amount`,`a`.`check_nb` AS `check_nb`,concat(`a`.`prefix`,`a`.`main_nb`) AS `trans_nb`,`a`.`value_date` AS `value_date`,`pr`.`project_name` AS `project_name`,`a`.`project_id` AS `project_id`,`a`.`prefix` AS `prefix`,`a`.`salesman_id` AS `salesman_id`,`a`.`activity_id` AS `activity_id`,`activity_tree`.`activity_code` AS `activity_code`,`activity_tree`.`activity_title` AS `activity_title`,`ca`.`main_type` AS `acc_main_type`,`ca`.`sub_type` AS `acc_sub_type`,ifnull(`subtype`.`subtype_name`,'') AS `subtype_name`,ifnull(`subtype`.`subtype_abbrv`,'') AS `subtype_abbrv`,`a`.`main_nb` AS `main_nb`,`a`.`is_locked` AS `is_locked`,`a`.`date_time` AS `date_time`,`cu`.`User_Full_Name` AS `created_user`,`modified_user`.`User_Full_Name` AS `modified_user`,if(isnull(`a`.`subtype`),concat(`a`.`prefix`,`a`.`main_nb`),concat(`a`.`prefix`,`subtype`.`subtype_abbrv`,`a`.`main_nb`)) AS `manual_jv_nb` from ((((((((((`tbl_accounting_transactions` `a` left join `tbl_common_currency` `c` on((`c`.`Currency_ID` = `a`.`Currency_ID`))) left join `tbl_chart_of_accounts` `ca` on((`ca`.`Account_ID` = `a`.`Account_ID`))) left join `tbl_common_users` `u` on((`u`.`User_ID` = `a`.`Logged_ID`))) left join `tbl_organization_branches` `b` on((`b`.`branch_id` = `a`.`branch_id`))) left join `tbl_accounting_jobs` `aj` on((`aj`.`job_id` = `a`.`job_id`))) left join `tbl_projects` `pr` on((`pr`.`project_id` = `a`.`project_id`))) left join `tbl_activity_tree` `activity_tree` on((`activity_tree`.`activity_id` = `a`.`activity_id`))) left join `tbl_accounting_transaction_subtype` `subtype` on((`subtype`.`subtype_id` = `a`.`subtype`))) left join `tbl_common_users` `cu` on((`cu`.`User_ID` = `a`.`created_logged_id`))) left join `tbl_common_users` `modified_user` on((`modified_user`.`User_ID` = `a`.`Logged_ID`))) order by `a`.`JV_ID` desc ;

