DROP TABLE IF EXISTS `transfer_details_list`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `transfer_details_list`  AS  select `details`.`Entry_ID` AS `Entry_ID`,`details`.`Request_ID` AS `Request_ID`,`details`.`Product_ID` AS `Product_ID`,`details`.`Request_Qty` AS `Request_Qty`,`details`.`Request_UOM` AS `Request_UOM`,`details`.`Current_Quantity` AS `Current_Quantity`,`details`.`expiry_date` AS `expiry_date`,`details`.`lot_nb` AS `lot_nb`,`details`.`serial_nb` AS `serial_nb`,`products`.`Product_Name` AS `Product_Name`,`uom`.`UOM_Name` AS `UOM_Name`,`main`.`Request_Date` AS `Request_Date`,`main`.`serial_prefix` AS `serial_prefix`,`main`.`Request_Number` AS `Request_Number`,concat_ws('',`main`.`serial_prefix`,`main`.`Request_Number`) AS `req_nb`,`main`.`Request_From` AS `Request_From`,`main`.`Request_To` AS `Request_To`,`main`.`parent_request_id` AS `parent_request_id`,`main`.`ticketing_id` AS `ticketing_id`,`main`.`customer_id` AS `customer_id`,`main`.`Status_ID` AS `Status_ID`,`from_depot`.`Depot_Name` AS `depot_from`,`to_depot`.`Depot_Name` AS `depot_to`,ifnull(`customers`.`Customer_Name`,'') AS `Customer_Name`,`main`.`is_consignment` AS `is_consignment`,`main`.`current_year_id` AS `current_year_id`,ifnull(`suppliers`.`Supplier_Name`,'') AS `Supplier_Name`,ifnull(concat(`employee`.`Employee_FirstName`,' ',`employee`.`Employee_MiddleName`,' ',`employee`.`Employee_LastName`,' '),'') AS `Employee_Name`,if((`main`.`customer_id` <> 0),ifnull(`customers`.`Customer_Name`,''),if((`main`.`supplier_id` <> 0),ifnull(`suppliers`.`Supplier_Name`,''),ifnull(concat(`employee`.`Employee_FirstName`,' ',`employee`.`Employee_MiddleName`,' ',`employee`.`Employee_LastName`,' '),''))) AS `person_name`,`main`.`supplier_id` AS `supplier_id`,`from_depot`.`branch_id` AS `f_branch_id`,`to_depot`.`branch_id` AS `t_branch_id`,`products`.`brand_id` AS `brand_id`,`products`.`sub_supplier_id` AS `sub_supplier_id`,`brand`.`brand_name` AS `brand_name`,`main`.`current_rate` AS `current_rate`,`details`.`unit_price` AS `unit_price`,((`details`.`unit_price` * `main`.`current_rate`) * `details`.`Current_Quantity`) AS `total_price`,`category`.`Cat_Name` AS `Cat_Name`,`products`.`Category_ID` AS `Category_ID`,`uom_conversion`.`Bar_Code` AS `Bar_Code`,`main`.`virtual_depot_id` AS `virtual_depot_id`,`main`.`is_delivered` AS `is_delivered`,`details`.`delivered_current_qty` AS `delivered_current_qty` from (((((((((((`tbl_stock_request_details` `details` join `tbl_stock_request` `main` on((`main`.`Request_ID` = `details`.`Request_ID`))) join `tbl_stock_products` `products` on((`products`.`Product_ID` = `details`.`Product_ID`))) join `tbl_stock_uom` `uom` on((`uom`.`UOM_ID` = `details`.`Request_UOM`))) join `tbl_stock_depot_warehouse` `from_depot` on((`from_depot`.`Depot_ID` = `main`.`Request_From`))) join `tbl_stock_depot_warehouse` `to_depot` on((`to_depot`.`Depot_ID` = `main`.`Request_To`))) left join `tbl_customers` `customers` on((`customers`.`Customer_ID` = `main`.`customer_id`))) left join `tbl_stock_suppliers` `suppliers` on((`suppliers`.`Supplier_ID` = `main`.`supplier_id`))) left join `tbl_hrm_employee` `employee` on((`employee`.`Employee_ID` = `main`.`employee_id`))) left join `tbl_brand_products` `brand` on((`brand`.`brand_id` = `products`.`brand_id`))) join `tbl_product_cat` `category` on((`category`.`Cat_ID` = `products`.`Category_ID`))) join `tbl_uom_conversions` `uom_conversion` on(((`uom_conversion`.`uom_from` = `details`.`Request_UOM`) and (`uom_conversion`.`Product_ID` = `details`.`Product_ID`) and (ifnull(`details`.`dynamic_param1_id`,0) = ifnull(`uom_conversion`.`uom_dynamic_param1_id`,0))))) ;

