CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `user_activities`  AS  select concat(`i`.`invoice_prefix`,`i`.`Invoice_ID`) AS `number`,(`i`.`Invoice_Net_Total` * `i`.`current_rate`) AS `invoice_total`,(`i`.`Invoice_Net_Total` * `i`.`second_currency_rate`) AS `invoice_total_usd`,(`i`.`Invoice_Paid_Amount` * `i`.`current_rate`) AS `paid_amount`,(`i`.`Invoice_Paid_Amount` * `i`.`second_currency_rate`) AS `paid_amount_usd`,`c`.`Customer_Name` AS `Name`,'Invoice' AS `type`,`i`.`Invoice_Date` AS `Date`,`i`.`Logged_ID` AS `Logged_ID`,`u`.`User_Name` AS `User_Name`,`i`.`is_actual` AS `is_actual`,`i`.`Sales_ID` AS `Sales_ID`,`i`.`branch_id` AS `branch_id`,`i`.`current_rate` AS `current_rate`,`i`.`second_currency_rate` AS `second_currency_rate`,`c`.`branch_id` AS `customer_branch_id` from ((`tbl_invoices` `i` join `tbl_customers` `c` on((`i`.`Customer_ID` = `c`.`Customer_ID`))) join `tbl_common_users` `u` on((`u`.`User_ID` = `i`.`Logged_ID`))) ;

