--
-- Structure for view `user_invoices`
--
DROP TABLE IF EXISTS `user_invoices`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `user_invoices`  AS  select concat(`inv`.`invoice_prefix`,`inv`.`Invoice_ID`) AS `id`,`inv`.`date_time` AS `date_time`,if((isnull(`inv`.`pos_customer_id`) or (`inv`.`pos_customer_id` = 0)),`cust`.`Customer_Name`,`pc`.`customer_name`) AS `customer_name`,(`inv`.`Invoice_Net_Total` + `inv`.`Invoice_Shipping`) AS `total`,`inv`.`Invoice_Net_Total` AS `total_no_shipping`,`inv`.`Invoice_Shipping` AS `shipping`,((`inv`.`Invoice_Sub_Total` * `inv`.`Invoice_Discount`) / 100) AS `discount`,'Invoice' AS `type`,`inv`.`Logged_ID` AS `user`,`inv`.`Invoice_Currency` AS `currency`,`inv`.`Sales_ID` AS `Sales_ID`,`inv`.`is_actual` AS `is_actual`,`inv`.`Invoice_Paid_Amount` AS `total_cash`,`inv`.`Payment_Paid_Amount` AS `total_cash_receipt`,`inv`.`date_created` AS `date_created`,`inv`.`current_rate` AS `current_rate`,`inv`.`Class_ID` AS `class_id`,`inv`.`is_committed` AS `is_committed`,`inv`.`branch_id` AS `branch_id`,`inv`.`Invoice_Status` AS `Invoice_Status`,`inv`.`Invoice_Date` AS `inv_date`,`inv`.`Invoice_ID_Auto` AS `current_id`,`inv_users`.`User_Name` AS `User_Name`,`inv`.`pick_up_date` AS `pick_up_date`,`inv`.`drop_off_date` AS `drop_off_date`,`inv`.`shipping_status_id` AS `shipping_status_id`,`inv`.`created_logged_id` AS `created_logged_id`,`inv`.`shipping_company_id` AS `shipping_company_id`,`inv`.`Customer_ID` AS `current_customer_id`,`inv`.`customer_branch_id` AS `customer_branch_id`,`inv`.`is_empty_detail` AS `is_empty_detail`,`inv`.`invoice_subtype` AS `invoice_subtype`,`inv`.`second_currency_rate` AS `second_currency_rate`,`cu`.`Currency_Symbol` AS `Currency_Symbol`,`inv`.`vat1_total` AS `vat1_total`,`inv`.`vat2_total` AS `vat2_total`,`inv`.`vat3_total` AS `vat3_total`,`inv`.`Invoice_Sub_Total` AS `sub_total`,`inv`.`other_amount_currency` AS `other_amount_currency`,`inv`.`eft_paid_amount` AS `eft_paid_amount`,`inv`.`momo_paid_amount` AS `momo_paid_amount`,`inv`.`cash_amount` AS `cash_amount`,`inv`.`card_amount` AS `card_amount`,`inv`.`check_amount` AS `check_amount`,`inv`.`rpay_paid_amount` AS `rpay_paid_amount`,`inv`.`rpay_acc_id` AS `rpay_acc_id` from ((((`tbl_invoices` `inv` left join `tbl_customers` `cust` on((`inv`.`Customer_ID` = `cust`.`Customer_ID`))) left join `tbl_pos_customers` `pc` on((`pc`.`customer_id` = `inv`.`pos_customer_id`))) join `tbl_common_users` `inv_users` on((`inv_users`.`User_ID` = `inv`.`Logged_ID`))) join `tbl_common_currency` `cu` on((`cu`.`Currency_ID` = `inv`.`Invoice_Currency`))) union select concat(`ret`.`invoice_prefix`,`ret`.`Return_ID`) AS `id`,`ret`.`date_time` AS `date_time`,`cust`.`Customer_Name` AS `customer_name`,`ret`.`Return_Invoice_Total` AS `total`,`ret`.`Return_Invoice_Total` AS `total_no_shipping`,0 AS `shipping`,'' AS `discount`,'Return' AS `type`,`ret`.`Logged_ID` AS `user`,`ret`.`Currency_ID` AS `currency`,`ret`.`Sales_ID` AS `Sales_ID`,`ret`.`Is_Actual` AS `is_actual`,`ret`.`Return_Paid_Total` AS `total_cash`,0 AS `total_cash_receipt`,`ret`.`date_created` AS `date_created`,`ret`.`current_rate` AS `current_rate`,`ret`.`Class_ID` AS `class_id`,1 AS `is_committed`,`ret`.`branch_id` AS `branch_id`,if((`ret`.`Return_Paid_Total` = 0),0,if((`ret`.`Return_Paid_Total` < `ret`.`Return_Invoice_Total`),1,2)) AS `Invoice_Status`,`ret`.`Return_Invoice_Date` AS `inv_date`,`ret`.`Return_Invoice_ID` AS `current_id`,`ret_users`.`User_Name` AS `User_Name`,NULL AS `pick_up_date`,NULL AS `drop_off_date`,NULL AS `shipping_status_id`,`ret`.`created_logged_id` AS `created_logged_id`,NULL AS `shipping_company_id`,`ret`.`Person_ID` AS `current_customer_id`,`ret`.`customer_branch_id` AS `customer_branch_id`,0 AS `is_empty_detail`,0 AS `invoice_subtype`,`ret`.`second_currency_rate` AS `second_currency_rate`,`cu`.`Currency_Symbol` AS `Currency_Symbol`,`ret`.`vat1_total` AS `vat1_total`,`ret`.`vat2_total` AS `vat2_total`,0 AS `vat3_total`,`ret`.`Return_Invoice_Total` AS `sub_total`,0 AS `other_amount_currency`,`ret`.`eft_paid_amount` AS `eft_paid_amount`,`ret`.`momo_paid_amount` AS `momo_paid_amount`,`ret`.`cash_amount` AS `cash_amount`,`ret`.`card_amount` AS `card_amount`,`ret`.`check_amount` AS `check_amount`,`ret`.`rpay_paid_amount` AS `rpay_paid_amount`,`ret`.`rpay_acc_id` AS `rpay_acc_id` from (((`tbl_accounting_return_invoices` `ret` left join `tbl_customers` `cust` on((`ret`.`Person_ID` = `cust`.`Customer_ID`))) join `tbl_common_users` `ret_users` on((`ret_users`.`User_ID` = `ret`.`Logged_ID`))) join `tbl_common_currency` `cu` on((`cu`.`Currency_ID` = `ret`.`Currency_ID`))) where (`ret`.`Is_Customer_Invoice` = 1) ;

