--
DROP TABLE IF EXISTS `web_api_users`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `web_api_users`  AS  select `u`.`user_id` AS `user_id`,`u`.`title` AS `title`,`u`.`app_user_id` AS `app_user_id`,`u`.`class_id` AS `class_id`,`u`.`depot_id` AS `depot_id`,`u`.`other_data` AS `other_data`,`d`.`Depot_Name` AS `Depot_Name`,`d`.`Depot_Code` AS `Depot_Code`,`c`.`Class_Name` AS `Class_Name`,`su`.`User_Name` AS `username` from (((`tbl_web_api_users` `u` join `tbl_pricing_class` `c` on((`c`.`Class_ID` = `u`.`class_id`))) join `tbl_stock_depot_warehouse` `d` on((`d`.`Depot_ID` = `u`.`depot_id`))) join `tbl_common_users` `su` on((`su`.`User_ID` = `u`.`app_user_id`))) ;

-- --------------------------------------------------------

--
-- Structure for view `weekly_bundle_list`
--
DROP TABLE IF EXISTS `weekly_bundle_list`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `weekly_bundle_list`  AS  select `bundle`.`weekly_bundle_id` AS `weekly_bundle_id`,`bundle`.`prdct_id` AS `prdct_id`,`bundle`.`unit_id` AS `unit_id`,`bundle`.`prdct_total` AS `prdct_total`,`prdcts`.`Product_Name` AS `Product_Name`,`uom`.`UOM_Name` AS `UOM_Name` from ((`tbl_weekly_bundle` `bundle` join `tbl_stock_products` `prdcts` on((`bundle`.`prdct_id` = `prdcts`.`Product_ID`))) join `tbl_stock_uom` `uom` on((`uom`.`UOM_ID` = `bundle`.`unit_id`))) ;

